-- abilities: 215 rows
INSERT INTO abilities (id, name_ja, effect_text) VALUES
(1, 'しんりょく', 'HPが1/3以下の時、『くさ』タイプの攻撃技を使用した時の『こうげき』『とくこう』が1.5倍になる。'),
(2, 'ようりょくそ', '天気が『にほんばれ』の時、『すばやさ』が2倍になる。'),
(5, 'あついしぼう', '『ほのお』『こおり』タイプの技を受けた時、ダメージが半減する。'),
(6, 'もうか', 'HPが1/3以下の時、『ほのお』タイプの攻撃技を使用した時の『こうげき』『とくこう』が1.5倍になる。'),
(7, 'サンパワー', '天気が『にほんばれ』の時、『とくこう』が1.5倍になるが、毎ターン終了時に最大HPの1/8のダメージを受ける。'),
(8, 'かたいツメ', '接触技(直接攻撃)の威力が1.3倍になる。'),
(9, 'ひでり', '戦闘に出ると5ターンの間、天気が『にほんばれ』になる。'),
(10, 'げきりゅう', 'HPが1/3以下の時、『みず』タイプの攻撃技を使用した時の『こうげき』『とくこう』が1.5倍になる。'),
(11, 'あめうけざら', '天気が『あめ』の時毎ターン、HPが最大HPの1/16回復する。'),
(12, 'メガランチャー', '波動系の技『あくのはどう』『はどうだん』『みずのはどう』『りゅうのはどう』『だいちのはどう』『こんげんのはどう』の技の威力が1.5倍になり、『いやしのはどう』は最大HPの3/4回復する。'),
(13, 'むしのしらせ', 'HPが1/3以下の時、『むし』タイプの攻撃技を使用した時の『こうげき』『とくこう』が1.5倍になる。'),
(14, 'スナイパー', '自分の攻撃が急所に当たると、ダメージが1.5倍ではなく2.25倍になる。'),
(15, 'てきおうりょく', '自分の『タイプ』と同じ『タイプ』の技のダメージが1.5倍ではなく2倍になる。テラスタル状態の時は、テラスタイプのみが対象となり、テラスタイプが元のタイプと同じ場合は2.25倍、異なる場合は2倍になる。'),
(16, 'するどいめ', '命中率ランクが下がらない。また、相手の回避率ランクの変化の影響を受けない。'),
(17, 'ちどりあし', '『こんらん』状態の時、回避率が2倍に上がる。'),
(18, 'はとむね', '相手の『ぼうぎょ』ランクを下げる技や特性の効果を受けない。'),
(19, 'ノーガード', 'お互いに技が命中率・回避率に関係なく必ず命中する。技『そらをとぶ』『とびはねる』『フリーフォール』『あなをほる』『ダイビング』『ゴーストダイブ』『シャドーダイブ』を使っている時でも命中する。'),
(20, 'いかく', '戦闘に出た時に相手全体の『こうげき』ランクを1段階ずつ下げる。第8世代からは、特性『きもったま』『せいしんりょく』『どんかん』『マイペース』の相手には無効。'),
(21, 'だっぴ', 'ターンごとに30%の確率で状態異常が治る。'),
(22, 'きんちょうかん', 'すべての相手は『きのみ』を使用できなくなる。'),
(23, 'せいでんき', '接触技(直接攻撃)を受けると、30%の確率で相手を『まひ』状態にする。'),
(24, 'ひらいしん', '『でんき』タイプの技を受けるとダメージが無効化され、自分の『とくこう』ランクが1段階上がる。またダブルバトルの時、自分以外の全てのポケモンの『でんき』タイプの単体攻撃技の攻撃対象が自分になる。(攻撃対象が複数の技の場合はそのまま)'),
(27, 'メロメロボディ', '異性のポケモンから接触技(直接攻撃)を受けると、30%の確率で相手を『メロメロ』状態にする。性別が同じ場合や、性別不明の場合は効果がない。'),
(28, 'マジックガード', '直接のダメージ以外を受けない。具体的には、『どく』『もうどく』『やけど』状態や特性『さめはだ』『てつのトゲ』『とびだすなかみ』『ヘドロえき』『ゆうばく』、天気『すなあらし』、技『あくむ』『うずしお』『からではさむ』『サンダープリズン』『しおづけ』『しめつける』『ステルスロック』『すなじごく』『トラバサミ』『のろい』『はじけるほのお』『ふんじん』『ほのおのうず』『ほのおのちかい』『まきつく』『まきびし』『マグマストーム』『まとわりつく』『やどりぎのタネ』によるダメージ、反動のある技による反動ダメージや失敗時に受けるダメージ、『ニードルガード』『ふんじん』によるダメージ、道具『いのちのたま』『くっつきバリ』『くろいヘドロ』『ゴツゴツメット』の効果によるダメージを受けない。ただし『こんらん』『じばく』『だいばくはつ』『わるあがき』などには影響しない。'),
(29, 'てんねん', '相手の『こうげき』『ぼうぎょ』『とくこう』『とくぼう』ランクおよび『回避率』『命中率』ランクの変化の影響を受けない。(素早さは除く)'),
(30, 'マジックミラー', '技『マジックコート』で跳ね返すことのできる技を跳ね返せる。'),
(31, 'もらいび', '『ほのお』タイプの技を受けるとダメージや効果はなくなり、以後自分の『ほのお』タイプの技の威力が1.5倍になる。'),
(35, 'せいぎのこころ', '『あく』タイプの攻撃技でダメージを受けると、『こうげき』ランクが1段階上がる。'),
(36, 'シンクロ', '相手の技や特性によって『どく』『もうどく』『まひ』『やけど』状態になった時、相手を同じ状態異常にする。'),
(37, 'せいしんりょく', '相手の技で『ひるみ』状態にならない。なお、技『きあいパンチ』には影響しない。相手の特性『いかく』の効果も受けない。(第7世代までは『いかく』の効果は受ける)'),
(39, 'トレース', '場に出た時、相手と同じ特性になる。相手が2体いる場合はランダムにどちらかの特性が選ばれる。相手の特性が『ARシステム』『アイスフェイス』『イリュージョン』『おもかげやどし』『かがくのちから』『かがくへんかガス』『かわりもの』『きずなへんげ』『ぎょぐん』『クォークチャージ』『こだいかっせい』『しれいとう』『じんばいったい』『スワームチェンジ』『ぜったいねむり』『ゼロフォーミング』『ダルマモード』『テラスシェル』『てんきや』『どくくぐつ』『トレース』『ばけのかわ』『バトルスイッチ』『はらぺこスイッチ』『フラワーギフト』『マイティチェンジ』『マルチタイプ』『リミットシールド』『レシーバー』の場合は効果がなく、相手が別の特性のポケモンとなった時に発動する。'),
(40, 'こんじょう', '状態異常の時、『こうげき』が1.5倍になる。またその時、『やけど』状態による『こうげき』半減の効果を受けない。'),
(42, 'ふくつのこころ', '相手の技でひるむと、『すばやさ』ランクが1段階上がる。'),
(44, 'くいしんぼう', 'HPが最大HPの1/4となると発動する『きのみ』が通常より早く、最大HPの半分以下になった時に『きのみ』を使う。'),
(45, 'とびだすなかみ', '相手の技のダメージによって『ひんし』になった時、その最後の技を受けた時に残っていたHP分のダメージを技を使った相手に与える。'),
(46, 'どんかん', '『メロメロ』『ちょうはつ』『ゆうわく』状態にならない。第8世代からは、相手の特性『いかく』の効果も受けない。'),
(47, 'マイペース', '『こんらん』状態にならない。第8世代からは、相手の特性『いかく』の効果も受けない。'),
(48, 'さいせいりょく', '他のポケモンに交代するとHPが最大HPの1/3回復する。'),
(49, 'シェルアーマー', '自分への攻撃は急所に当たらない。'),
(50, 'のろわれボディ', '相手から技を受けた時、30%の確率で3ターンの間、その相手の技を『かなしばり』状態にする。技が無効化された場合や、自分が『みがわり』状態の場合は発動しない。'),
(51, 'かげふみ', '相手は逃げたり、ポケモンを交代することができなくなる。相手が『ゴースト』タイプや特性『かげふみ』の場合は無効。'),
(52, 'はやおき', '『ねむり』状態の時、ねむり状態のターン経過が2倍になり、通常より早く回復する。'),
(53, 'きもったま', '相手が『ゴースト』タイプでも、『ノーマル』『かくとう』タイプの技が等倍で当たる。第8世代からは、相手の特性『いかく』の効果も受けない。'),
(55, 'おやこあい', '同じ技を1ターンに2回攻撃できる。2回目の攻撃は、威力が0.25倍になる。能力ランクを下げるなどの効果は2回分与えられる。1ターンに連続して攻撃する技や、複数の相手に攻撃する技の場合は2回攻撃できない。(第6世代は2回目威力0.5倍)'),
(56, 'はっこう', '(第9世代から)命中率ランクが下がらない。また、相手の回避率ランクの変化の影響を受けない。'),
(57, 'しぜんかいふく', '他のポケモンに交代すると状態異常が回復する。'),
(58, 'アナライズ', '自分の攻撃がターンで一番最後の時、技の威力が1.3倍になる。'),
(59, 'ちからもち', '攻撃時の自分の『こうげき』が2倍になる。なお、技『イカサマ』の場合も、相手の『こうげき』を自分の能力にコピーした後に2倍にして攻撃する。'),
(60, 'かいりきバサミ', '相手の技や特性で『こうげき』ランクが下がらない。'),
(61, 'かたやぶり', '相手の特性の影響を受けずに攻撃できる。ただし、攻撃後に受ける効果は消えない。'),
(62, 'じしんかじょう', '自分の技で相手を倒すと、『こうげき』ランクが1段階上がる。'),
(63, 'スカイスキン', '自分の『ノーマル』タイプの技が『ひこう』タイプになり、さらに威力が1.2倍になる(第6世代は1.3倍)。ダイマックスすると、『ダイジェット』になるが、威力の補正はない。'),
(65, 'いかりのつぼ', '自分への攻撃が急所に当たると、『こうげき』ランクが最大まで上がる。'),
(66, 'ちからずく', '追加効果のある技を使うと、追加効果が発動しない代わりに威力が1.3倍になる。また、追加効果がある技を使うと、道具『いのちのたま』の反動効果や『かいがらのすず』の回復効果を受けない。攻撃対象の相手の道具『だっしゅつボタン』『レッドカード』『アッキのみ』『タラプのみ』および特性『にげごし』『ききかいひ』『へんしょく』『わるいてぐせ』『ぎゃくじょう』の効果も発動させない。なお、自分の能力ランクを下げる技や反動技、ダイマックス技は追加効果の対象ではない。『ひみつのちから』『かげぬい』『うたかたのアリア』『アンカーショット』『ぶきみなじゅもん』『がんせきアックス』『ひけん・ちえなみ』『いっちょうあがり』『みずあめボム』は対象となる。'),
(69, 'はんすう', '『きのみ』を食べた次のターンの終了時にも、もう1度同じ『きのみ』を食べることができる。'),
(79, 'じゅうなん', '『まひ』状態にならない。'),
(80, 'かわりもの', '戦闘に出ると、相手のポケモンに変身し、『へんしん』状態になる。ダブルバトルでは正面の相手に変身するため、正面のポケモンがいない場合は失敗する。'),
(81, 'ちょすい', '『みず』タイプの技を受けるとダメージや効果はなくなり、最大HPの1/4回復する。'),
(82, 'うるおいボディ', '天気が『あめ』の時、ターン終了時に状態異常が回復する。'),
(83, 'ちくでん', '『でんき』タイプの技を受けるとダメージや効果はなくなり、最大HPの1/4回復する。'),
(84, 'はやあし', '状態異常の時、『すばやさ』が1.5倍になる。またその時、『まひ』状態による『すばやさ』が遅くなる効果を受けない。'),
(87, 'いしあたま', '技『アフロブレイク』『ウッドハンマー』『じごくぐるま』『すてみタックル』『とっしん』『フレアドライブ』『ブレイブバード』『ボルテッカー』『もろはのずつき』『ワイルドボルト』『ウェーブタックル』『クロロブラスト』の反動を受けない。技『わるあがき』の反動は受ける。'),
(88, 'プレッシャー', '技を受けた時、相手の技のPPを1多く減らす(合計2減る)。自分自身が対象の技などには効果がない。(ダブルバトルでこの特性を持つ2体のポケモンに範囲攻撃を与えると、合計3減る)'),
(91, 'めんえき', '『どく』『もうどく』状態にならない。'),
(95, 'マルチスケイル', '自分の残りHPが最大値の時、受けるダメージが半減される。'),
(98, 'リーフガード', '天気が『にほんばれ』の時、状態異常にならない。'),
(99, 'メガソーラー', '自分が技を使った時だけ、実際の天気に関係なく、天気が『にほんばれ』状態の時と同じ効果になる。(天気が変わるわけではない)'),
(104, 'ドラゴンスキン', '自分の『ノーマル』タイプの技が『ドラゴン』タイプになり、さらに威力が1.2倍になる。(ダイマックスすると、『ダイドラグーン』になるが、威力の補正はない。)'),
(106, 'ふみん', '『ねむり』状態や『ねむけ』状態にならない。技『ねむる』を使えない。この特性を獲得する前に『ねむり』状態になっていた場合は、『ねむり』状態を回復する。'),
(109, 'プラス', '特性『プラス』か『マイナス』のポケモンが戦闘にいると『とくこう』が1.5倍になる。'),
(113, 'そうしょく', '『くさ』タイプの技を受けると技が無効化され、『こうげき』ランクが1段階上がる。'),
(115, 'しめりけ', '全てのポケモンは技『じばく』『だいばくはつ』『ビックリヘッド』『ミストバースト』が失敗し、また特性『ゆうばく』が無効になる。'),
(116, 'あめふらし', '戦闘に出ると5ターンの間、天気が『あめ』になる。'),
(124, 'がんじょう', 'HPが最大の時、『ひんし』状態になるダメージを受けても必ず1残る。また、一撃で『ひんし』になる技『じわれ』『ぜったいれいど』『つのドリル』『ハサミギロチン』を受けない。'),
(125, 'ぼうじん', '天気『すなあらし』によるダメージを受けない。粉系の技『いかりのこな』『キノコのほうし』『しびれごな』『どくのこな』『ねむりごな』『ふんじん』『まほうのこな』『わたほうし』、特性『ほうし』の効果を受けない。'),
(129, 'すなのちから', '天気が『すなあらし』の時、自分の『じめん』『いわ』『はがね』タイプの技の威力が1.3倍になる。また、『すなあらし』によるダメージを受けない。'),
(131, 'テクニシャン', '威力が60以下の技の威力が1.5倍になる。基礎威力が変動する技は、変動後の威力で判定する。'),
(132, 'ライトメタル', '自分の『おもさ』が半分になる。(技『けたぐり』『くさむすび』対策などで有効)'),
(137, 'スキルリンク', '1ターンに複数回連続で攻撃する技『おうふくビンタ』『スイープビンタ』『スケイルショット』『タネマシンガン』『たまなげ』『つっぱり』『つららばり』『とげキャノン』『ボーンラッシュ』『ミサイルばり』『みずしゅりけん』『みだれづき』『みだれひっかき』『れんぞくパンチ』『ロックブラスト』『トリプルキック』『トリプルアクセル』『ネズミざん』が1度目が成功すれば、必ず最大回数当たる。'),
(140, 'くだけるよろい', '物理技を受けると、『ぼうぎょ』ランクが1段階下がり、『すばやさ』ランクが2段階上がる。(第6世代は1段階)'),
(141, 'すじがねいり', '特性『ひらいしん』『よびみず』や技『いかりのこな』『このゆびとまれ』『サイドチェンジ』『スポットライト』の攻撃対象を変更する効果の影響を受けずに攻撃できる。'),
(146, 'すなおこし', '戦闘に出ると5ターンの間、天気が『すなあらし』になる。'),
(154, 'テレパシー', '味方の技のダメージを受けない。'),
(155, 'フェアリースキン', '自分の『ノーマル』タイプの技が『フェアリー』タイプになり、さらに威力が1.2倍になる(第6世代は1.3倍)。ダイマックスすると、『ダイフェアリー』になるが、威力の補正はない。'),
(157, 'あとだし', '技を出す順番が必ず一番最後になる。'),
(158, 'いたずらごころ', '自分の使う変化技の優先度が1だけ加算される。優先度0の変化技も優先度+1として『すばやさ』に関係なく先制攻撃できる。ただし『あく』タイプの相手(味方は含まない)には変化技がすべて失敗する(第6世代は条件なし)。'),
(162, 'ヘヴィメタル', '自分の『おもさ』が2倍になる。(技『ヘビーボンバー』などで有効)'),
(163, 'フィルター', 'タイプ相性が『こうかは ばつぐん』の技の受けるダメージが3/4になる。例えば、2倍弱点の場合は1.5倍のダメージになる。'),
(164, 'ヨガパワー', '攻撃時の自分の『こうげき』が2倍になる。なお、技『イカサマ』の場合も、相手の『こうげき』を自分の能力にコピーした後に2倍にして攻撃する。'),
(169, 'マイナス', '特性『プラス』か『マイナス』のポケモンが戦闘にいると『とくこう』が1.5倍になる。'),
(171, 'さめはだ', '接触技(直接攻撃)を受けると、相手のHPを相手の最大HPの1/8減らす。'),
(172, 'かそく', '毎ターン、『すばやさ』ランクが1段階ずつ上がる。'),
(173, 'がんじょうあご', 'あごやキバを使って攻撃する技『かみつく』『かみくだく』『ひっさつまえば』『ほのおのキバ』『かみなりのキバ』『こおりのキバ』『どくどくのキバ』『サイコファング』『エラがみ』『くらいつく』の威力が1.5倍になる。'),
(174, 'マグマのよろい', '『こおり』状態にならない。'),
(175, 'ハードロック', 'タイプ相性が『こうかは ばつぐん』の技の受けるダメージが3/4になる。例えば、本来2倍弱点の場合は1.5倍のダメージに軽減される。'),
(178, 'しろいけむり', '相手の能力ランクを下げる技や特性の効果を受けない。'),
(182, 'ノーてんき', '全てのポケモンに対しての天気の影響がなくなる。'),
(184, 'ふしぎなうろこ', '状態異常の時、『ぼうぎょ』が1.5倍になる。'),
(185, 'かちき', '相手の技や特性で能力ランクが下がると、『とくこう』ランクが2段階上がる。自分や味方の技や特性で下がった場合は効果がない。'),
(187, 'てんきや', '天気が『にほんばれ』の時は『ほのお』タイプに、『あめ』の時は『みず』タイプに、『ゆき』の時は『こおり』タイプになり、姿がそれぞれ変化する。');
INSERT INTO abilities (id, name_ja, effect_text) VALUES
(189, 'おみとおし', '戦闘に出てきた時、すべての相手の持っている道具の名前が分かる。'),
(192, 'ふゆう', '『じめん』タイプの技を受けない。また、技『どくびし』『まきびし』『ねばねばネット』や特性『ありじごく』の効果を受けない。『エレキフィールド』『サイコフィールド』『グラスフィールド』『ミストフィールド』の効果も受けない。'),
(195, 'きょううん', '急所ランクが1段階上がった状態となり、自分の攻撃が急所に当たりやすくなる。'),
(199, 'アイスボディ', '天気が『ゆき』の時、毎ターン終了時にHPが最大HPの1/16回復する。'),
(200, 'ムラっけ', '毎ターン終了時、『こうげき』『ぼうぎょ』『とくこう』『とくぼう』『すばやさ』いずれかのランクが2段階上がり、別のランクが1段階下がる。(第7世代までは『回避率』『命中率』も含まれていた)'),
(201, 'フリーズスキン', '自分の『ノーマル』タイプの技が『こおり』タイプになり、さらに威力が1.2倍になる。(第6世代は1.3倍)'),
(205, 'てつのこぶし', 'パンチ系の技『アイスハンマー』『アームハンマー』『かみなりパンチ』『きあいパンチ』『グロウパンチ』『コメットパンチ』『シャドーパンチ』『スカイアッパー』『ドレインパンチ』『ばくれつパンチ』『バレットパンチ』『ピヨピヨパンチ』『プラズマフィスト』『ほのおのパンチ』『マッハパンチ』『メガトンパンチ』『れいとうパンチ』『れんぞくパンチ』『ダブルパンツァー』『あんこくきょうだ』『すいりゅうれんだ』『ぶちかまし』『ジェットパンチ』『ふんどのこぶし』の威力が1.2倍になる。'),
(208, 'とうそうしん', '性別が同じ相手に対しては『こうげき』『とくこう』が1.25倍になるが、異なる場合は0.75倍になる。性別のないポケモンの場合は変化なし。'),
(212, 'どくのトゲ', '接触技(直接攻撃)を受けると、30%の確率で相手を『どく』状態にする。'),
(217, 'ぼうおん', '音系の技『いにしえのうた』『いびき』『いやしのすず』『いやなおと』『うたう』『うたかたのアリア』『エコーボイス』『おしゃべり』『おたけび』『きんぞくおん』『くさぶえ』『さわぐ』『スケイルノイズ』『すてゼリフ』『チャームボイス』『ちょうおんぱ』『とおぼえ』『ないしょばなし』『なきごえ』『バークアウト』『ハイパーボイス』『ばくおんぱ』『ほえる』『ほろびのうた』『むしのさざめき』『りんしょう』『ブレイジングソウルビート』『オーバードライブ』『ぶきみなじゅもん』『フレアソング』『みわくのボイス』『サイコノイズ』を受けない。'),
(219, 'ぶきよう', '持っている道具の効果が発揮されない。'),
(223, 'すりぬけ', '相手の『オーロラベール』『リフレクター』『ひかりのかべ』『しろいきり』『しんぴのまもり』『みがわり』の効果を受けない。'),
(224, 'すながくれ', '天気が『すなあらし』の時、相手から受ける技の命中率が0.8倍になる。また、『すなあらし』によるダメージを受けない。'),
(233, 'きけんよち', '戦闘に出てきた時、相手が『こうかは ばつぐん』や一撃必殺となる技を持っているかが分かる。技の名前などは分からない。'),
(234, 'かんそうはだ', '『ほのお』タイプの技の受けるダメージが1.25倍になる。『みず』タイプの技を受けると、ダメージを受けずHPが最大HPの1/4回復する。また、天気が『にほんばれ』の時は毎ターン最大HPの1/8のダメージを受け、『あめ』の時は毎ターンHPが最大HPの1/8回復する。'),
(235, 'どくしゅ', '相手に接触技(直接攻撃)で攻撃すると、30%の確率で相手を『どく』状態にする。(相手が『おんみつマント』『りんぷん』の場合は発動しない)'),
(236, 'ゆきふらし', '戦闘に出ると5ターンの間、天気が『ゆき』になる。'),
(240, 'わるいてぐせ', '接触技(直接攻撃)を受けた時、自分が道具を持っていなければ、相手の持っている道具を奪う。'),
(243, 'すてみ', '技『アフロブレイク』『ウッドハンマー』『じごくぐるま』『すてみタックル』『とっしん』『とびげり』『とびひざげり』『もろはのずつき』『フレアドライブ』『ブレイブバード』『ボルテッカー』『ワイルドボルト』『ウェーブタックル』『かかとおとし』『サンダーダイブ』の威力が1.2倍になる。'),
(246, 'ゆきがくれ', '天気が『ゆき』の時、相手の技の命中率が0.8倍になる。'),
(250, 'ポイズンヒール', '『どく』状態の時毎ターン、HPが減らずに最大HPの1/8だけ回復する。『もうどく』状態でも回復量は変わらない。'),
(255, 'きれあじ', '切る技『アクアカッター』『いあいぎり』『エアカッター』『エアスラッシュ』『がんせきアックス』『きょじゅうざん』『きりさく』『クロスポイズン』『サイコカッター』『サイコブレイド』『シェルブレード』『シザークロス』『しんぴのつるぎ』『せいなるつるぎ』『ソーラーブレード』『タキオンカッター』『つじぎり』『つばめがえし』『ドゲザン』『ネズミざん』『はっぱカッター』『パワフルエッジ』『ひけん・ちえなみ』『むねんのつるぎ』『リーフブレード』『れんぞくぎり』『フェイタルクロー』『ドラゴンクロー』『シャドークロー』『ブレイククロー』の威力が1.5倍になる。'),
(268, 'あまのじゃく', '能力ランクを変化させる技の効果が逆になる(1段階上がるものは1段階下がる)。ダイマックス技の追加効果は影響を受けるが、第7世代の変化技のZワザによる追加効果については影響を受けない。'),
(278, 'かるわざ', '持っている道具がなくなると『すばやさ』が2倍になる。再び道具を持つと元に戻る。最初から道具を持っていない場合は効果がない。'),
(286, 'すなかき', '天気が『すなあらし』の時、『すばやさ』が2倍になる。また、『すなあらし』によるダメージを受けない。'),
(289, 'かんつうドリル', '接触技(直接攻撃)を使うと、相手の『まもる』『みきり』『たたみがえし』『トーチカ』『キングシールド』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』『ファストガード』『ワイドガード』の守りの効果を無視して、本来の1/4のダメージを与える。相手の守りの効果以外は発動される。'),
(290, 'いやしのこころ', '毎ターン終了時、50%の確率で自分以外の味方の状態異常が治る。(ポケモンSVまでは1/3の確率)'),
(303, 'ミイラ', '接触技(直接攻撃)を受けると、相手の特性を『ミイラ』にする(相手の本来の特性を無効化する)。'),
(304, 'あくしゅう', '相手に攻撃技のダメージを与えると、10%の確率でひるませる。(相手が『おんみつマント』『りんぷん』の場合は発動しない)'),
(306, 'ゆうばく', '相手の接触技(直接攻撃)で『ひんし』になった時、相手に相手の最大HPの1/4のダメージを与える。'),
(307, 'イリュージョン', '手持ちの最後のポケモンの姿と名前で戦闘に出る。『タイプ』や能力に変化はない。ダメージを受けると元に戻る。'),
(308, 'サーフテール', '場の状態が『エレキフィールド』の時、『すばやさ』が2倍になる。'),
(314, 'クイックドロウ', '素早さに関係なく、30%の確率で同じ優先度の攻撃技を先制攻撃できる。変化技には効果がない。'),
(319, 'きみょうなくすり', '戦闘に出た時、味方のポケモンの能力ランクの変化をもとに戻す。上がったランクも戻る。(ダブルバトル用)'),
(332, 'でんきエンジン', '『でんき』タイプの技を受けるとダメージや効果はなくなり、『すばやさ』ランクが1段階上がる。'),
(334, 'ほのおのからだ', '接触技(直接攻撃)を受けると、30%の確率で相手を『やけど』状態にする。'),
(338, 'ゆきかき', '天気が『ゆき』の時、『すばやさ』が2倍になる。'),
(339, 'すいすい', '天気が『あめ』の時、『すばやさ』が2倍になる。'),
(343, 'ぎたい', '場フィールドの状態にあわせて、自分の『タイプ』が変化する。『エレキフィールド』では『でんき』タイプ、『グラスフィールド』では『くさ』タイプ、『サイコフィールド』では『エスパー』タイプ、『ミストフィールド』では『フェアリー』になる。フィールドが戻ると、タイプも元に戻る。'),
(347, 'ふかしのこぶし', '接触技(直接攻撃)を使うと、相手の『まもる』『みきり』『たたみがえし』『トーチカ』『キングシールド』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』『ファストガード』『ワイドガード』の守りの効果を無視して、本来の1/4のダメージを与える。相手の守りの効果以外は発動される。(ポケモンSVまでは完全に貫通し、相手の技の効果も発動しなかった)'),
(352, 'ぼうだん', 'たま・爆弾系の技『アイスボール』『アシッドボム』『ウェザーボール』『エナジーボール』『エレキボール』『オクタンほう』『かえんだん』『かえんボール』『かふんだんご』『がんせきほう』『きあいだま』『くちばしキャノン』『ジャイロボール』『シャドーボール』『タネばくだん』『タネマシンガン』『タマゴばくだん』『たまなげ』『でんじほう』『どろばくだん』『はどうだん』『ヘドロばくだん』『マグネットボム』『ミストボール』『ロックブラスト』『みずあめボム』を無効化する。'),
(355, 'マジシャン', '自分の攻撃時、自分が道具を持っていなければ、技を当てた相手が持っている道具を奪う。'),
(358, 'へんげんじざい', '場に出てから最初に技を出す時、技を出す直前のタイミングで自分のタイプが技と同じタイプになる(タイプは変化したままになる)。変化技にも有効。(第8世代までは何度も変更可能)'),
(360, 'ものひろい', '毎ターン終了時に、そのターンに相手や味方(相手が優先)が消費した道具を拾って自分のものにする。自分が道具を持っていない時のみ発動する。『だっしゅつボタン』『ふうせん』には効果がない。'),
(361, 'ほおぶくろ', '自分の持っている『きのみ』を食べる時、本来の効果に加えて、さらにHPも最大HPの1/3回復する。'),
(364, 'はやてのつばさ', '自分の残りHPが最大値の時、優先度0の『ひこう』タイプの技を『すばやさ』に関係なく先制攻撃できる(優先度:+1)。(第6世代はHPの条件なし)'),
(365, 'りんぷん', '技の追加効果を受けない。具体的には、追加効果として受ける状態異常やランク補正、『ひるみ』状態、『しおづけ』状態などを防げる。'),
(366, 'ふくがん', '命中率が1.3倍になる。'),
(367, 'フレンドガード', '自分以外の味方が受けるダメージが3/4に軽減される。(ダブルバトル用)'),
(368, 'フラワーベール', '味方すべての『くさ』タイプのポケモンは、味方自身以外の技や特性によって能力ランクを下げられず、状態異常にもならない。'),
(369, 'きょうせい', '味方が道具を使ったり失った時、自分の持っている道具を味方に移動する。'),
(370, 'フェアリーオーラ', 'お互いのすべてのポケモンの『フェアリー』タイプの技の威力が4/3倍(1.33倍)になる。'),
(376, 'ファーコート', '物理攻撃の受けるダメージが半減する。'),
(385, 'バトルスイッチ', '攻撃技を使用する場合ブレードフォルムになり(攻撃・特攻が高い)、技『キングシールド』を使用するとシールドフォルムになる(防御・特防が高い)。'),
(388, 'アロマベール', '自分と味方へのメンタル攻撃技『アンコール』『いちゃもん』『かいふくふうじ』『かなしばり』『ちょうはつ』『メロメロ』を無効化する。'),
(389, 'スイートベール', '自分や味方のポケモンは『ねむり』状態と『ねむけ』状態にならない。'),
(410, 'ぬめぬめ', '接触技(直接攻撃)を受けると、相手の『すばやさ』ランクを1段階下げる。'),
(418, 'しゅうかく', 'ターン終了時、自分が最後に使用した『きのみ』が50%の確率で元に戻る。天気が『にほんばれ』の時は100%の確率で元に戻る。'),
(441, 'えんかく', '自分の使う技はすべて接触技(直接攻撃)ではなくなる。'),
(447, 'うるおいボイス', '自分の音系の技『いにしえのうた』『いびき』『いやしのすず』『いやなおと』『うたう』『うたかたのアリア』『エコーボイス』『おしゃべり』『おたけび』『きんぞくおん』『くさぶえ』『さわぐ』『スケイルノイズ』『すてゼリフ』『チャームボイス』『ちょうおんぱ』『とおぼえ』『ないしょばなし』『なきごえ』『バークアウト』『ハイパーボイス』『ばくおんぱ』『ほえる』『ほろびのうた』『むしのさざめき』『りんしょう』『ソウルビート』『オーバードライブ』『ぶきみなじゅもん』『フレアソング』『みわくのボイス』『サイコノイズ』の『タイプ』がすべて『みず』タイプになる。'),
(460, 'やるき', '『ねむり』状態や『ねむけ』状態にならない。技『ねむる』を使えない。この特性を獲得する前に『ねむり』状態になっていた場合は、『ねむり』状態を回復する。'),
(462, 'ひとでなし', '相手が『どく』『もうどく』状態の時、自分の攻撃が必ず急所に当たる。'),
(466, 'じきゅうりょく', '技のダメージを受けると、『ぼうぎょ』ランクが1段階上がる。'),
(468, 'すいほう', '『みず』タイプの技の威力が2倍になる。また、『ほのお』タイプの技を受けた時、ダメージが半減する。さらに『やけど』状態にならない。'),
(470, 'ふしょく', '『どく』『はがね』タイプのポケモンも『どく』『もうどく』状態にできる。'),
(473, 'じょおうのいげん', '自分と味方は、相手の先制技を受けない。なお、自分が使う先制技や味方から受ける先制技には影響しない。'),
(478, 'レシーバー', '場にいる味方のポケモンが『ひんし』状態になった時、自分の特性がそのポケモンと同じ特性になる。場から離れると元に戻る(ダブルバトル用)。味方の特性が『ARシステム』『アイスフェイス』『イリュージョン』『おもかげやどし』『かがくのちから』『かがくへんかガス』『かわりもの』『きずなへんげ』『ぎょぐん』『クォークチャージ』『こだいかっせい』『しれいとう』『じんばいったい』『スワームチェンジ』『ぜったいねむり』『ゼロフォーミング』『ダルマモード』『テラスシェル』『てんきや』『どくくぐつ』『トレース』『ばけのかわ』『バトルスイッチ』『はらぺこスイッチ』『ふしぎなまもり』『フラワーギフト』『マイティチェンジ』『マルチタイプ』『リミットシールド』『レシーバー』の場合は効果がない。'),
(479, 'まけんき', '相手の技や特性で能力ランクが下がった時、自分の『こうげき』ランクが2段階上がる。自分や味方の技や特性で下がった場合は効果がない。'),
(480, 'ばけのかわ', '1回だけ相手の技のダメージや『こんらん』状態による自傷ダメージを無効化し、フォルムチェンジする(能力などは変化しない)。その時、第8世代からは最大HPの1/8のダメージを受ける。ダメージ以外の効果や、状態異常、天気や道具、特性によるダメージなどには影響しない。一度フォルムチェンジすると、場から離れてもバトル中は元に戻らない。'),
(481, 'ぎゃくじょう', '相手の技のダメージで自分の残りHPが半分以下になると、『とくこう』ランクが1段階上がる。相手の技のダメージ以外の場合や、すでに残りHPが半分以下の場合は発動しない。'),
(490, 'ミラーアーマー', '能力ランクを下げる効果を受けずに、相手に跳ね返す。技の追加効果の場合も含める。'),
(491, 'じゅくせい', '『きのみ』を使う時、効果が2倍になる。例えば、『オボンのみ』は最大HPの1/2回復し、『ジャポのみ』『レンブのみ』は最大HPの1/4のダメージを与える。'),
(493, 'はりきり', '物理技を使用する時、『こうげき』が1.5倍になるが、命中率が0.8倍になる。'),
(497, 'すなはき', '技のダメージを受けると、5ターンの間、天気が『すなあらし』になる。'),
(506, 'バリアフリー', '戦闘に出た時、お互いの場の『ひかりのかべ』『リフレクター』『オーロラベール』の状態を解除する。'),
(508, 'さまようたましい', '接触技(直接攻撃)を受けると、自分と相手の特性を入れ替える。'),
(511, 'はらぺこスイッチ', 'ターン終了時、『まんぷくもよう』と『はらぺこもよう』を交互にフォルムチェンジする。技『オーラぐるま』のタイプが、『まんぷく』の時は『でんき』、『はらぺこ』の時は『あく』タイプに変わる。'),
(512, 'クリアボディ', '相手の能力ランクを下げる技や特性の効果を受けない。'),
(536, 'びんじょう', '相手の能力ランクが上がった時、自分も同じように能力ランクが上がる。'),
(540, 'テイルアーマー', '自分と味方は、相手の先制技を受けない。なお、自分が使う先制技や味方から受ける先制技には影響しない。'),
(542, 'マイティチェンジ', '手持ちに戻ると、『マイティフォルム』にフォルムチェンジする。'),
(547, 'とびだすハバネロ', '技のダメージを受けると、相手を『やけど』状態にする。'),
(548, 'でんきにかえる', '攻撃を受けた時に『じゅうでん』状態(でんき威力アップ状態)になり、一度だけ次回使う自分の『でんき』タイプの技の威力が2倍になる。'),
(551, 'どしょく', '『じめん』タイプの技を受けると、ダメージを受けずHPが最大HPの1/4回復する。'),
(556, 'きよめのしお', '状態異常にならない。技『ねむる』を使えない。また、『ゴースト』タイプの技の受けるダメージが半減する。'),
(559, 'どくげしょう', '物理技のダメージを受けると、相手の場を『どくびし』状態にし、相手はポケモンを交代する度に、出したポケモンが『どく』状態になる。(2度物理技を受けたあとは『もうどく』状態)'),
(570, 'そうだいしょう', '場に出た時に、これまでに『ひんし』状態になった味方のポケモン数×10%だけ技の威力が上がる。(最大1.5倍)'),
(572, 'かんろなミツ', '最初に戦闘に出た時に相手全体の『回避率』ランクを1段階ずつ下げる。1回の戦闘で1度しか発動しない。'),
(574, 'ねんちゃく', '持っている道具を相手に奪われない。'),
(578, 'おもてなし', '戦闘に出た時に、自分を除く味方全体のHPをそれぞれ最大HPの1/4ずつ回復する。(ダブルバトル用)'),
(579, 'たいねつ', '『ほのお』タイプの技を受けた時と、『やけど』状態によるダメージが半減する。'),
(583, 'うなぎのぼり', '特性『ふゆう』と『ビーストブースト』の効果をあわせ持つ。具体的には、『じめん』タイプの技を受けず、また技『どくびし』『まきびし』『ねばねばネット』や特性『ありじごく』の効果を受けない。『エレキフィールド』『サイコフィールド』『グラスフィールド』『ミストフィールド』の効果も受けない。また、さらに、自分の技で相手を倒すと、自分の最も高い能力の能力ランクが1段階上がる。'),
(584, 'おうごんのからだ', '相手や味方の変化技を受けない。'),
(590, 'きゅうばん', '相手を交代させる技『ふきとばし』『ほえる』『ドラゴンテール』『ともえなげ』や、道具『レッドカード』の効果を受けない。'),
(611, 'ほうし', NULL),
(612, 'ほのおのたてがみ', '『ほのお』タイプの技の威力が1.5倍になる。'),
(616, 'もふもふ', NULL),
(619, 'よちむ', '戦闘に出ると相手の覚えている技のうち、最も威力の高い技の名前が分かる。同じ威力の技がある場合はランダム。'),
(621, 'エレキメイカー', '戦闘に出ると5ターンの間、場の状態を『エレキフィールド』にする。(『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、『ねむり』状態にならず、また『でんき』タイプの技の威力が1.3倍になる)'),
(622, 'カブトアーマー', '自分への攻撃は急所に当たらない。');
INSERT INTO abilities (id, name_ja, effect_text) VALUES
(630, 'びびり', '『ゴースト』『むし』『あく』タイプの技を受けた時、『すばやさ』ランクが1段階上がる。第8世代からは、相手の特性『いかく』で『こうげき』が下がった時にも発動する。'),
(631, 'ヘドロえき', 'HPを吸い取る技『きゅうけつ』『ギガドレイン』『すいとる』『ちからをすいとる』『デスウイング』『ドレインキッス』『ドレインパンチ』『パラボラチャージ』『むねんのつるぎ』『メガドレイン』『やどりぎのタネ』『ゆめくい』を受けた時、逆に相手に本来回復する分のダメージを与える。『ちからをすいとる』は、『こうげき』ランクを下げる効果はある。'),
(632, 'はどうのぼうご', '接触技(直接攻撃)の受けるダメージが半減する。'),
(633, 'くさのけがわ', '場の状態が『グラスフィールド』の時、『ぼうぎょ』が1.5倍になる。'),
(634, 'ききかいひ', '相手の技のダメージで自分の残りHPが半分以下になると、他の手持ちのポケモンと交代する。相手の技のダメージ以外の場合や、すでに残りHPが半分以下の場合は発動しない。なお、野生のポケモンが相手の場合は交代せずに逃げ出す。'),
(635, 'グラスメイカー', '戦闘に出ると5ターンの間、場の状態を『グラスフィールド』にする。(『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、毎ターン最大HPの1/16ずつ回復し、また『くさ』タイプの技の威力が1.3倍になり、技『じしん』『じならし』『マグニチュード』の威力が半減する)'),
(636, 'リベロ', '場に出てから最初に技を出す時、技を出す直前のタイミングで自分のタイプが技と同じタイプになる(タイプは変化したままになる)。変化技にも有効。(第8世代までは何度も変更可能)'),
(637, 'にげあし', '技『くろいまなざし』など逃げたり交代できなくなる技や、特性『ありじごく』『かげふみ』などの交代を封じる効果を受けず、必ず交代できる。'),
(638, 'はりこみ', '相手がポケモンを交代する時に攻撃すると、交代して出てきたポケモンに2倍のダメージを与える。'),
(639, 'パンクロック', '自分の音系の技『いにしえのうた』『いびき』『うたかたのアリア』『エコーボイス』『さわぐ』『スケイルノイズ』『チャームボイス』『バークアウト』『ハイパーボイス』『ばくおんぱ』『むしのさざめき』『りんしょう』『オーバードライブ』『ぶきみなじゅもん』『フレアソング』『みわくのボイス』『サイコノイズ』の威力が1.3倍になる。また、自分が受ける音系の技のダメージが半減する。'),
(640, 'はがねのせいしん', '自分と味方の『はがね』タイプの技の威力が1.5倍になる。この特性のポケモンが複数いる場合は、効果が重複する。'),
(641, 'サイコメイカー', '戦闘に出ると5ターンの間、場の状態を『サイコフィールド』にする。(『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、相手(味方は含まない)の先制技を受けなくなり、また『エスパー』タイプの技の威力が1.3倍になる)'),
(642, 'こぼれダネ', '攻撃を受けると5ターンの間、場の状態を『グラスフィールド』にする。(『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、毎ターン最大HPの1/16ずつ回復し、また『くさ』タイプの技の威力が1.3倍になり、技『じしん』『じならし』『マグニチュード』の威力が半減する)'),
(643, 'ばんけん', '相手の特性『いかく』の効果を受けず、『こうげき』ランクが1段階上がる。また、相手を交代させる技『ふきとばし』『ほえる』『ドラゴンテール』『ともえなげ』や、道具『レッドカード』の効果を受けない。'),
(644, 'ねつこうかん', '『ほのお』タイプの攻撃技でダメージを受けると、『こうげき』ランクが1段階上がる。また、『やけど』状態にならない。この特性を獲得する前に『やけど』状態になっていた場合は、『やけど』状態を回復する。');

-- moves: 511 rows
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(1, 'ギガインパクト', 'ノーマル', 'physical', '物理', 150, 90, 8, 0, 1, 'single', 0, '使用した次のターンは行動できない。'),
(2, 'すてみタックル', 'ノーマル', 'physical', '物理', 120, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。'),
(3, 'のしかかり', 'ノーマル', 'physical', '物理', 85, 100, 16, 0, 1, 'single', 0, '30%の確率で相手を『まひ』状態にする。相手が技『ちいさくなる』を使用していると必ず命中し、威力が2倍になる。'),
(4, 'からげんき', 'ノーマル', 'physical', '物理', 70, 100, 20, 0, 1, 'single', 0, '自分が『どく』『まひ』『やけど』状態の時、威力が2倍になる。『やけど』による『こうげき』の半減の影響を受けない。'),
(5, 'はかいこうせん', 'ノーマル', 'special', '特殊', 150, 90, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(6, 'りんしょう', 'ノーマル', 'special', '特殊', 60, 100, 16, 0, 0, 'single', 0, '同じターンに他のポケモンも『りんしょう』を使おうとすると、『すばやさ』に関係なく最初に使用したポケモンに続いて使用でき、最初以外の『りんしょう』は威力が2倍になる。音系の技。相手の『みがわり』状態を貫通する。(ダブルバトル用)'),
(7, 'だいちのはどう', 'ノーマル', 'special', '特殊', 50, 100, 12, 0, 0, 'single', 0, '場の状態がフィールドで、自分が『ひこう』タイプや特性『ふゆう』などではなく地面にいる時、技のタイプが変化し、威力も2倍になる(フィールドの1.3倍の効果もさらに加わる)。『グラスフィールド』の時は『くさ』タイプ、『ミストフィールド』の時は『フェアリー』タイプ、『エレキフィールド』の時は『でんき』タイプ、『サイコフィールド』の時は『エスパー』タイプの技となる。'),
(8, 'ウェザーボール', 'ノーマル', 'special', '特殊', 50, 100, 12, 0, 0, 'single', 0, '天気が『にほんばれ』の時は『ほのお』タイプ、『あめ』の時は『みず』タイプ、『ゆき』の時は『こおり』タイプ、『すなあらし』の時は『いわ』タイプになり、威力が2倍になる。ダイマックス技や第7世代のZワザもタイプが変わる。'),
(9, 'いびき', 'ノーマル', 'special', '特殊', 50, 100, 16, 0, 0, 'single', 0, '自分が『ねむり』状態の時のみ使用可能。30%の確率で相手をひるませる。音系の技。相手の『みがわり』状態を貫通する。'),
(10, 'てだすけ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+5)。使用したターンの間、味方の技の威力を1.5倍にする。'),
(11, 'あまいかおり', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'all_opponents', 1, '相手全体が対象。相手の回避率を2段階下げる。'),
(12, 'ねごと', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分が『ねむり』状態の時のみ使用可能。自分の持っている技のうち1つをランダムで使う。PPが減少するのはこの技のみ。'),
(13, 'こらえる', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '必ず先制できる(優先度:+4)。そのターンに『ひんし』状態になる攻撃を受けてもHPが1残る。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。'),
(14, 'こわいかお', 'ノーマル', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手の『すばやさ』ランクを2段階下げる。'),
(15, 'まもる', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '必ず先制でき(優先度:+4)、そのターンの間、相手の技を受けない。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。ダイマックス技や第7世代のZワザの攻撃技は貫通し、1/4のダメージを受ける。'),
(16, 'みがわり', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分のHPを最大HPの1/4だけ減らして、減らしたHPと同じHPの自分の分身を作り、分身のHPが0になるまですべての攻撃を自分の代わりに分身が受ける。分身は状態異常にならない。ただし、音系の技などはそのまま受ける。相手のダイマックス技も防げるが、自分がダイマックスすると分身が消える。'),
(17, 'ほえる', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '必ず後攻になる(優先度:-6)。相手のポケモンを強制的に交代させる。野生のポケモンの場合は戦闘を終了する。自分の命中率、相手の回避率に関係なく必ず命中する。相手の『まもる』『みきり』『トーチカ』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』の効果を受けない。音系の技。相手の『みがわり』状態を貫通する。ダイマックスしている相手には無効。野生のポケモンの場合、相手が自分のレベルより高い場合は失敗する。'),
(18, 'つるぎのまい', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『こうげき』ランクを2段階上げる。'),
(19, 'パワーウィップ', 'くさ', 'physical', '物理', 120, 85, 12, 0, 1, 'single', 0, '通常攻撃。'),
(20, 'はなふぶき', 'くさ', 'physical', '物理', 90, 100, 16, 0, 0, 'all_except_self', 1, '自分以外全員が対象。通常攻撃。'),
(21, 'タネばくだん', 'くさ', 'physical', '物理', 80, 100, 16, 0, 0, 'single', 0, '通常攻撃。'),
(22, 'グラススライダー', 'くさ', 'physical', '物理', 55, 100, 20, 0, 1, 'single', 0, '場の状態が『グラスフィールド』で、自分が『ひこう』タイプや特性『ふゆう』などではなく地面にいる時、必ず先制できる(優先度:+1)。'),
(23, 'くさわけ', 'くさ', 'physical', '物理', 50, 100, 20, 0, 1, 'single', 0, '100%の確率で自分の『すばやさ』ランクが1段階上がる。'),
(24, 'タネマシンガン', 'くさ', 'physical', '物理', 25, 100, 20, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(25, 'ハードプラント', 'くさ', 'special', '特殊', 150, 90, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(26, 'リーフストーム', 'くさ', 'special', '特殊', 130, 90, 8, 0, 0, 'single', 0, '攻撃後、100%の確率で自分の『とくこう』ランクが2段階下がる。'),
(27, 'はなびらのまい', 'くさ', 'special', '特殊', 120, 100, 12, 0, 1, 'single', 0, '自分は『あばれ』状態となり、2～3ターン連続で攻撃し、他の行動はできない。その後1～4ターンの間『こんらん』状態になる。'),
(28, 'ソーラービーム', 'くさ', 'special', '特殊', 120, 100, 12, 0, 0, 'single', 0, '1ターン目は攻撃せずに、2ターン目で攻撃する。天気が『にほんばれ』の時は1ターンためずに攻撃でき、『あめ』『ゆき』『すなあらし』の時は威力が半分になる。'),
(29, 'エナジーボール', 'くさ', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(30, 'ギガドレイン', 'くさ', 'special', '特殊', 75, 100, 12, 0, 0, 'single', 0, '相手に与えたダメージの半分だけ自分のHPが回復する。'),
(31, 'くさむすび', 'くさ', 'special', '特殊', NULL, 100, 20, 0, 1, 'single', 0, '相手の『おもさ』が重いほど威力が高くなる。10kg未満は20、25kg未満は40、50kg未満は60、100kg未満は80、200kg未満は100、それ以上は120。ダイマックスしている相手には無効。'),
(32, 'グラスフィールド', 'くさ', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、場の状態を『グラスフィールド』にする。『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、毎ターン最大HPの1/16ずつ回復し、また『くさ』タイプの技の威力が1.3倍になり(第7世代までは1.5倍)、技『じしん』『じならし』『マグニチュード』の威力が半減する。また、道具『グラスシード』を持ったポケモンは『ぼうぎょ』ランクが1段階上がる(この効果は、地面にいないポケモンでも発動する)。'),
(33, 'なやみのタネ', 'くさ', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手の特性を『ふみん』にする。ただし、『なまけ』『バトルスイッチ』など一部の固有な特性の場合は失敗する。'),
(34, 'ねをはる', 'くさ', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '使用後、毎ターン、HPが最大HPの1/16ずつ回復するが、交代できなくなる。自分が『ひこう』タイプや、特性『ふゆう』のポケモンの場合は『じめん』タイプの技が当たるようになる。'),
(35, 'こうごうせい', 'くさ', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが、天気が通常の時は最大HPの1/2、『にほんばれ』の時は最大HPの2/3、『あめ』『ゆき』『すなあらし』の時は最大HPの1/4回復する。'),
(36, 'ねむりごな', 'くさ', 'status', '変化', NULL, 75, 16, 0, 0, 'single', 0, '相手を『ねむり』状態にする。『くさ』タイプや特性『ぼうじん』、道具『ぼうじんゴーグル』を持っているポケモンには無効。'),
(37, 'せいちょう', 'くさ', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『こうげき』『とくこう』ランクが1段階ずつ上がる。天気が『にほんばれ』の時は、2段階ずつ上がる。'),
(38, 'やどりぎのタネ', 'くさ', 'status', '変化', NULL, 90, 12, 0, 0, 'single', 0, '使用後、毎ターン、相手のHPを最大HPの1/8ずつ減らし、その分自分のHPを回復させる。自分は交代しても効果が引き継ぐ。『くさ』タイプのポケモンには無効。'),
(39, 'にほんばれ', 'ほのお', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、天気を『にほんばれ』にする。『ほのお』タイプの技のダメージが1.5倍になり、『みず』タイプの技のダメージが半減する。『こおり』状態にならない。'),
(40, 'どくづき', 'どく', 'physical', '物理', 80, 100, 20, 0, 1, 'single', 0, '30%の確率で相手を『どく』状態にする。'),
(41, 'ヘドロウェーブ', 'どく', 'special', '特殊', 95, 100, 12, 0, 0, 'all_except_self', 1, '自分以外全員が対象。10%の確率で相手を『どく』状態にする。'),
(42, 'ヘドロばくだん', 'どく', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '30%の確率で相手を『どく』状態にする。'),
(43, 'ベノムショック', 'どく', 'special', '特殊', 65, 100, 12, 0, 0, 'single', 0, '相手が『どく』『もうどく』状態の時、威力が2倍になる。'),
(44, 'アシッドボム', 'どく', 'special', '特殊', 40, 100, 20, 0, 0, 'single', 0, '100%の確率で相手の『とくぼう』ランクを2段階下げる。'),
(45, 'どくどく', 'どく', 'status', '変化', NULL, 90, 12, 0, 0, 'single', 0, '相手を『もうどく』状態にする。『もうどく』状態は通常の『どく』状態と違い、受けるダメージが1/16、2/16、3/16・・・と増えていく。『どく』タイプのポケモンが使うと必ず命中する。『どく』タイプや『はがね』タイプには無効。'),
(46, 'どくのこな', 'どく', 'status', '変化', NULL, 75, 20, 0, 0, 'single', 0, '相手を『どく』状態にする。『どく』タイプや『はがね』タイプ、『くさ』タイプ、特性『ぼうじん』、道具『ぼうじんゴーグル』を持っているポケモンには無効。'),
(47, 'じしん', 'じめん', 'physical', '物理', 100, 100, 12, 0, 0, 'all_except_self', 1, '自分以外全員が対象。相手が技『あなをほる』を使っている時でも命中し、ダメージが2倍になる。『グラスフィールド』の時、威力が半減する。'),
(48, 'じだんだ', 'じめん', 'physical', '物理', 75, 100, 12, 0, 1, 'single', 0, '前のターンで自分が使った技が外れたり失敗したり、『まひ』『こんらん』『ひるみ』状態などで行動できなかった場合、威力が2倍になる。'),
(49, 'じならし', 'じめん', 'physical', '物理', 60, 100, 20, 0, 0, 'all_except_self', 1, '自分以外全員が対象。100%の確率で相手の『すばやさ』ランクを1段階下げる。『グラスフィールド』の時、威力が半減する。'),
(50, 'だいちのちから', 'じめん', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(51, 'ねむる', 'エスパー', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPと状態異常をすべて回復した後、2ターンの間『ねむり』状態になり、3ターン目で目を覚ます。'),
(52, 'ドわすれ', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『とくぼう』ランクを2段階上げる。'),
(53, 'ひかりのかべ', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '5ターンの間、相手の特殊攻撃のダメージを半分にする。味方が複数の場合は半分ではなく2/3になる。急所に当たった場合は軽減されない。交代しても効果は続く。'),
(54, 'のろい', 'ゴースト', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分のタイプが『ゴースト』タイプの時は自分のHPを最大HPの半分だけ減らして、相手を『のろい』状態にする。『のろい』状態になると毎ターン、HPが最大HPの1/4ずつ減る。それ以外のポケモンの場合『すばやさ』ランクが1段階下がり、『こうげき』『ぼうぎょ』ランクが1段階ずつ上がる。'),
(55, 'げきりん', 'ドラゴン', 'physical', '物理', 120, 100, 12, 0, 1, 'single', 0, '自分は『あばれ』状態となり、2～3ターン連続で攻撃し、他の行動はできない。その後1～4ターンの間『こんらん』状態になる。'),
(56, 'はたきおとす', 'あく', 'physical', '物理', 65, 100, 20, 0, 1, 'single', 0, '相手が道具を持っている場合、威力が1.5倍になり、さらに道具を持っていない状態にする。戦闘終了後、道具は元に戻る。'),
(57, 'あまえる', 'フェアリー', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『こうげき』ランクを2段階下げる。'),
(70, 'かげぶんしん', 'ノーマル', 'status', '変化', NULL, NULL, 16, 0, 0, 'self', 0, '自分の回避率を1段階上げる。'),
(72, 'リフレクター', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '5ターンの間、相手の物理攻撃のダメージを半分にする。味方が複数の場合は半分ではなく2/3になる。急所に当たった場合は軽減されない。交代しても効果は続く。'),
(75, 'どろかけ', 'じめん', 'special', '特殊', 20, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の命中率を1段階下げる。'),
(77, 'いばる', 'ノーマル', 'status', '変化', NULL, 85, 16, 0, 0, 'single', 0, '相手を1～4ターンの間『こんらん』状態にするが、相手の『こうげき』ランクを2段階上げてしまう。'),
(79, 'メロメロ', 'ノーマル', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手が自分とは異なる性別の場合、相手を『メロメロ』状態にする。『メロメロ』状態になると、50%の確率で相手は自分に攻撃できなくなる。自分と相手の性別が同じ時や、どちらかが性別不明の場合は失敗する。'),
(82, 'しんぴのまもり', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '5ターンの間、味方の場を『しんぴのまもり』状態にして、自分と味方のポケモンは状態異常と『こんらん』状態にならなくなる。交代しても効果は続く。'),
(99, 'しめつける', 'ノーマル', 'physical', '物理', 15, 85, 20, 0, 1, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(100, 'いとをはく', 'むし', 'status', '変化', NULL, 95, 20, 0, 0, 'all_opponents', 1, '相手全体が対象。相手の『すばやさ』ランクを2段階下げる。'),
(101, 'とおせんぼう', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '『ゴースト』タイプではない相手は逃げたり、交代できなくなる。自分が場を離れると効果は消える。'),
(237, 'メガトンキック', 'ノーマル', 'physical', '物理', 120, 75, 8, 0, 1, 'single', 0, '通常攻撃。'),
(247, 'はらだいこ', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分のHPを最大HPの半分だけ減らす代わりに、自分の『こうげき』ランクを最大まで上げる。'),
(254, 'フレアドライブ', 'ほのお', 'physical', '物理', 120, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。10%の確率で相手を『やけど』状態にする。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。'),
(255, 'やけっぱち', 'ほのお', 'physical', '物理', 75, 100, 12, 0, 1, 'single', 0, '前のターンで自分が使った技が外れたり失敗したり、『まひ』『こんらん』『ひるみ』状態などで行動できなかった場合、威力が2倍になる。'),
(256, 'ほのおのパンチ', 'ほのお', 'physical', '物理', 75, 100, 16, 0, 1, 'single', 0, '10%の確率で相手を『やけど』状態にする。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(257, 'ほのおのキバ', 'ほのお', 'physical', '物理', 65, 95, 16, 0, 1, 'single', 0, '10%の確率で相手を『やけど』状態にする。10%の確率で、相手をひるませる。'),
(258, 'ニトロチャージ', 'ほのお', 'physical', '物理', 50, 100, 20, 0, 1, 'single', 0, '100%の確率で自分の『すばやさ』ランクが1段階上がる。'),
(259, 'ヒートスタンプ', 'ほのお', 'physical', '物理', NULL, 100, 12, 0, 1, 'single', 0, '自分の『おもさ』が相手より重いほど威力が高くなる。相手の『おもさ』が自分の1/5以下なら120、1/4以下なら100、1/3以下なら80、1/2以下なら60、それ以上なら40。相手が技『ちいさくなる』を使用していると必ず命中し、威力が2倍になる。ダイマックスしている相手には無効。'),
(260, 'ブラストバーン', 'ほのお', 'special', '特殊', 150, 90, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(261, 'オーバーヒート', 'ほのお', 'special', '特殊', 130, 90, 8, 0, 0, 'single', 0, '攻撃後、100%の確率で自分の『とくこう』ランクが2段階下がる。'),
(262, 'だいもんじ', 'ほのお', 'special', '特殊', 110, 85, 8, 0, 0, 'single', 0, '10%の確率で相手を『やけど』状態にする。'),
(263, 'れんごく', 'ほのお', 'special', '特殊', 100, 50, 8, 0, 0, 'single', 0, '100%の確率で相手を『やけど』状態にする。'),
(264, 'ねっぷう', 'ほのお', 'special', '特殊', 95, 90, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。10%の確率で相手を『やけど』状態にする。'),
(265, 'かえんほうしゃ', 'ほのお', 'special', '特殊', 90, 100, 16, 0, 0, 'single', 0, '10%の確率で相手を『やけど』状態にする。'),
(266, 'ほのおのうず', 'ほのお', 'special', '特殊', 35, 85, 16, 0, 0, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(267, 'おにび', 'ほのお', 'status', '変化', NULL, 85, 16, 0, 0, 'single', 0, '相手を『やけど』状態にする。『ほのお』タイプには無効。'),
(269, 'かみなりパンチ', 'でんき', 'physical', '物理', 75, 100, 16, 0, 1, 'single', 0, '10%の確率で相手を『まひ』状態にする。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(270, 'そらをとぶ', 'ひこう', 'physical', '物理', 90, 95, 16, 0, 1, 'single', 0, '1ターン目に空中へ飛び上がり、2ターン目に攻撃する。空中にいる間は『うちおとす』『かぜおこし』『かみなり』『サウザンアロー』『スカイアッパー』『たつまき』『ぼうふう』以外の技を受けない。'),
(271, 'つばめがえし', 'ひこう', 'physical', '物理', 60, NULL, 20, 0, 1, 'single', 0, '自分の命中率、相手の回避率に関係なく必ず命中する。'),
(272, 'アクロバット', 'ひこう', 'physical', '物理', 55, 100, 16, 0, 1, 'single', 0, '自分が道具を持っていない時、威力が2倍になる。'),
(273, 'ぼうふう', 'ひこう', 'special', '特殊', 110, 70, 12, 0, 0, 'single', 0, '30%の確率で、相手を1～4ターンの間『こんらん』状態にする。天気が『あめ』の時は必ず命中し、『にほんばれ』の時は命中率が50%になる。相手が技『そらをとぶ』『とびはねる』『フリーフォール』を使っている時でも命中する。'),
(274, 'エアスラッシュ', 'ひこう', 'special', '特殊', 75, 95, 16, 0, 0, 'single', 0, '30%の確率で相手をひるませる。'),
(275, 'エアカッター', 'ひこう', 'special', '特殊', 60, 95, 20, 0, 0, 'all_opponents', 1, '相手全体が対象。急所に当たりやすい(急所ランク:+1)。'),
(276, 'はねやすめ', 'ひこう', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが最大HPの半分回復するが、そのターンは『ひこう』タイプではなくなる。'),
(277, 'いわなだれ', 'いわ', 'physical', '物理', 75, 90, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。30%の確率で相手をひるませる。'),
(278, 'がんせきふうじ', 'いわ', 'physical', '物理', 60, 95, 16, 0, 0, 'single', 0, '100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(279, 'げんしのちから', 'いわ', 'special', '特殊', 60, 100, 8, 0, 0, 'single', 0, '10%の確率で自分の『こうげき』『ぼうぎょ』『とくこう』『とくぼう』『すばやさ』ランクが1段階ずつ上がる。'),
(280, 'すなあらし', 'いわ', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、天気を『すなあらし』にする。『いわ』『じめん』『はがね』タイプではないポケモンは、毎ターン最大HPの1/16のダメージを受ける。また、『いわ』タイプのポケモンは『とくぼう』が1.5倍になる。'),
(282, 'あなをほる', 'じめん', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '1ターン目に地中に潜り、2ターン目に攻撃する。地中にいる間は『じしん』『マグニチュード』以外の技を受けない。'),
(284, 'ねっさのだいち', 'じめん', 'special', '特殊', 70, 100, 12, 0, 0, 'single', 0, '30%の確率で相手を『やけど』状態にする。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。'),
(285, 'きあいパンチ', 'かくとう', 'physical', '物理', 150, 100, 20, 0, 1, 'single', 0, '必ず後攻になり(優先度:-3)、攻撃するまでに技を受けると失敗してしまう。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(286, 'かわらわり', 'かくとう', 'physical', '物理', 75, 100, 16, 0, 1, 'single', 0, '相手の技『リフレクター』『ひかりのかべ』『オーロラベール』を解除して攻撃する。'),
(287, 'カウンター', 'かくとう', 'physical', '物理', NULL, 100, 20, 0, 1, 'single', 0, '相手の物理攻撃のダメージの2倍をその相手に与える。『ダブルバトル』の時は最後に受けた技のみ有効になる。必ず後攻になる(優先度:-5)。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(288, 'きあいだま', 'かくとう', 'special', '特殊', 120, 70, 8, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。');
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(290, 'シャドークロー', 'ゴースト', 'physical', '物理', 70, 100, 16, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(292, 'ドラゴンダイブ', 'ドラゴン', 'physical', '物理', 100, 75, 12, 0, 1, 'single', 0, '20%の確率で相手をひるませる。相手が『ちいさくなる』を使用していると必ず命中し、威力が2倍になる。'),
(293, 'ドラゴンクロー', 'ドラゴン', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '通常攻撃。'),
(294, 'ワイドブレイカー', 'ドラゴン', 'physical', '物理', 60, 100, 16, 0, 1, 'all_opponents', 1, '相手全体が対象。100%の確率で相手の『こうげき』ランクを1段階下げる。'),
(295, 'ドラゴンテール', 'ドラゴン', 'physical', '物理', 60, 90, 12, 0, 1, 'single', 0, '必ず後攻になる(優先度:-6)。攻撃後、相手のポケモンを強制的に交代させる。野生のポケモンの場合は戦闘を終了する。ダイマックスしている相手には追加効果は無効。'),
(296, 'スケイルショット', 'ドラゴン', 'physical', '物理', 25, 90, 20, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。その後、自分の『ぼうぎょ』ランクが1段階下がり、『すばやさ』ランクが1段階上がる。'),
(297, 'りゅうのはどう', 'ドラゴン', 'special', '特殊', 85, 100, 12, 0, 0, 'single', 0, '通常攻撃。'),
(298, 'ドラゴンエール', 'ドラゴン', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '自分を除く味方全体を『きゅうしょアップ』状態(急所ランク1段階)にして、今後使う技が急所に当たりやすくなる(すでに『きゅうしょアップ』状態の時は失敗する)。対象の味方が『ドラゴン』タイプの場合は、2段階上がる。音系の技。'),
(299, 'りゅうのまい', 'ドラゴン', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『こうげき』『すばやさ』ランクを1段階ずつ上げる。'),
(300, 'かみくだく', 'あく', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '20%の確率で相手の『ぼうぎょ』ランクを1段階下げる。'),
(301, 'ぶんまわす', 'あく', 'physical', '物理', 60, 100, 20, 0, 1, 'all_except_self', 1, '自分以外全員が対象。通常攻撃。'),
(302, 'かみつく', 'あく', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '30%の確率で相手をひるませる。'),
(303, 'なげつける', 'あく', 'physical', '物理', NULL, 100, 12, 0, 0, 'single', 0, '自分の持っている道具によって効果が変化する。投げつけた道具はなくなる。'),
(304, 'ふくろだたき', 'あく', 'physical', '物理', NULL, 100, 12, 0, 0, 'single', 0, '自分を含む『ひんし』や状態異常でない『てもち』のポケモンの数だけ攻撃する。'),
(305, 'アイアンテール', 'はがね', 'physical', '物理', 100, 75, 16, 0, 1, 'single', 0, '30%の確率で相手の『ぼうぎょ』ランクを1段階下げる。'),
(306, 'はがねのつばさ', 'はがね', 'physical', '物理', 70, 90, 20, 0, 1, 'single', 0, '10%の確率で自分の『ぼうぎょ』ランクが1段階上がる。'),
(307, 'ちきゅうなげ', 'かくとう', 'physical', '物理', NULL, 100, 20, 0, 1, 'single', 0, '自分のレベルと同じ値の固定ダメージを与える。チャンピオンズでは50ダメージ。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(315, 'ばくれつパンチ', 'かくとう', 'physical', '物理', 100, 50, 8, 0, 1, 'single', 0, '100%の確率で相手を1～4ターンの間『こんらん』状態にする。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(316, 'じわれ', 'じめん', 'physical', '物理', NULL, 30, 8, 0, 0, 'single', 0, '相手を『ひんし』状態にする。『ひこう』タイプには無効だが、それ以外のタイプ相性の影響を受けない。ダイマックスしている相手には無効。'),
(317, 'ブレイズキック', 'ほのお', 'physical', '物理', 85, 90, 12, 0, 1, 'single', 0, '10%の確率で相手を『やけど』状態にする。急所に当たりやすい(急所ランク:+1)。'),
(318, 'マジカルフレイム', 'ほのお', 'special', '特殊', 75, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『とくこう』ランクを1段階下げる。'),
(319, 'ダブルウイング', 'ひこう', 'physical', '物理', 40, 90, 12, 0, 1, 'single', 0, '1ターンに2回連続で攻撃する。'),
(320, 'おいかぜ', 'ひこう', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '4ターンの間、自分と味方の『すばやさ』が2倍になる。'),
(321, 'きりばらい', 'ひこう', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '相手の回避率を1段階下げる。相手の場の『しろいきり』『ひかりのかべ』『リフレクター』『しんぴのまもり』『オーロラベール』、両方の場の『まきびし』『どくびし』『ステルスロック』『ねばねばネット』、さらに第8世代からは『エレキフィールド』『グラスフィールド』『サイコフィールド』『ミストフィールド』の効果を解除する。相手が『みがわり』状態の場合、回避率を下げる効果のみ失敗する。'),
(501, 'こうそくスピン', 'ノーマル', 'physical', '物理', 50, 100, 20, 0, 1, 'single', 0, '自分が受けている技『うずしお』『からではさむ』『サンダープリズン』『しめつける』『すなじごく』『トラバサミ』『ほのおのうず』『マグマストーム』『まきつく』『やどりぎのタネ』および自分の場の『ステルスロック』『どくびし』『まきびし』『ねばねばネット』の効果を解除する。第8世代からは、攻撃後、100%の確率で自分の『すばやさ』ランクが1段階上がる。(第7世代までは威力20)'),
(502, 'ねこだまし', 'ノーマル', 'physical', '物理', 40, 100, 12, 0, 1, 'single', 0, '必ず先制でき(優先度:+3)、100%の確率で相手をひるませる。ただし、出た最初のターンしか成功しない。'),
(503, 'じたばた', 'ノーマル', 'physical', '物理', NULL, 100, 16, 0, 1, 'single', 0, '自分の残りHPが少ないほど威力が高くなる。(威力は20～200)'),
(509, 'からをやぶる', 'ノーマル', 'status', '変化', NULL, NULL, 16, 0, 0, 'self', 0, '自分の『ぼうぎょ』『とくぼう』ランクが1段階ずつ下がり、『こうげき』『とくこう』『すばやさ』ランクが2段階ずつ上がる。'),
(510, 'あくび', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '相手を『ねむけ』状態にして、次のターン終了時に相手を『ねむり』状態にする。ただし、そのポケモンが交代されると効果は消える。自分の命中率、相手の回避率に関係なく必ず命中する。'),
(518, 'ウェーブタックル', 'みず', 'physical', '物理', 120, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。'),
(519, 'アクアテール', 'みず', 'physical', '物理', 90, 90, 12, 0, 1, 'single', 0, '通常攻撃。'),
(520, 'アクアブレイク', 'みず', 'physical', '物理', 85, 100, 12, 0, 1, 'single', 0, '20%の確率で、相手の『ぼうぎょ』ランクを1段階下げる。'),
(521, 'ダイビング', 'みず', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '1ターン目に水中へ潜り、2ターン目に攻撃する。水中にいる間は『なみのり』『うずしお』以外の技を受けない。'),
(522, 'たきのぼり', 'みず', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '20%の確率で相手をひるませる。'),
(523, 'クイックターン', 'みず', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '攻撃後、手持ちのポケモンと入れ替わる。'),
(524, 'アクアジェット', 'みず', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。'),
(525, 'しおふき', 'みず', 'special', '特殊', 150, 100, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。自分のHPが少ないほど技の威力が下がる。(150×自分の残りHP÷自分の最大HP)が威力。'),
(526, 'ハイドロカノン', 'みず', 'special', '特殊', 150, 90, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(527, 'ハイドロポンプ', 'みず', 'special', '特殊', 110, 80, 8, 0, 0, 'single', 0, '通常攻撃。'),
(528, 'だくりゅう', 'みず', 'special', '特殊', 90, 85, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。30%の確率で相手の命中率を1段階下げる。'),
(529, 'なみのり', 'みず', 'special', '特殊', 90, 100, 16, 0, 0, 'all_except_self', 1, '自分以外全員が対象。相手が『ダイビング』を使っている時でも命中し、ダメージが2倍になる。'),
(530, 'みずのはどう', 'みず', 'special', '特殊', 60, 100, 20, 0, 0, 'single', 0, '20%の確率で相手を1～4ターンの間『こんらん』状態にする。'),
(531, 'ひやみず', 'みず', 'special', '特殊', 50, 100, 20, 0, 0, 'single', 0, '100%の確率で相手の『こうげき』ランクを1段階下げる。'),
(532, 'うずしお', 'みず', 'special', '特殊', 35, 85, 16, 0, 0, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。相手が『ダイビング』を使っている時でも命中し、ダメージが2倍になる。'),
(533, 'いのちのしずく', 'みず', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と味方全体のHPをそれぞれ最大HPの1/4ずつ回復する。特性『ちょすい』『よびみず』の味方は特性が発動するため、この技の効果は無効。この技は『ダイウォール』の効果も受けない。'),
(534, 'アクアリング', 'みず', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '使用後、毎ターン、HPが最大HPの1/16ずつ回復する。'),
(535, 'あまごい', 'みず', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、天気を『あめ』にする。『みず』タイプの技のダメージが1.5倍になり、『ほのお』タイプの技のダメージが半減する。'),
(538, 'うちおとす', 'いわ', 'physical', '物理', 50, 100, 16, 0, 0, 'single', 0, '特性『ふゆう』や、『ひこう』タイプのポケモンに『じめん』タイプの技が当たるようになる。。また、空中状態の相手にも当たり、技『そらをとぶ』『とびはねる』『でんじふゆう』『テレキネシス』の効果が解除され、『でんじふゆう』『テレキネシス』は使用できなくなる。『フリーフォール』状態の相手にも命中する。'),
(542, 'マッドショット', 'じめん', 'special', '特殊', 55, 95, 16, 0, 0, 'single', 0, '100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(543, 'アイススピナー', 'こおり', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '場の状態『グラスフィールド』『ミストフィールド』『エレキフィールド』『サイコフィールド』を解除し、元に戻す。'),
(544, 'れいとうパンチ', 'こおり', 'physical', '物理', 75, 100, 16, 0, 1, 'single', 0, '10%の確率で相手を『こおり』状態にする。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(545, 'ゆきなだれ', 'こおり', 'physical', '物理', 60, 100, 12, 0, 1, 'single', 0, 'そのターンに相手の技のダメージを受けると威力が2倍になる。必ず後攻になる(優先度:-4)。'),
(546, 'ふぶき', 'こおり', 'special', '特殊', 110, 70, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。10%の確率で相手を『こおり』状態にする。天気が『ゆき』の時は必ず命中する。'),
(547, 'れいとうビーム', 'こおり', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '10%の確率で相手を『こおり』状態にする。'),
(548, 'こごえるかぜ', 'こおり', 'special', '特殊', 55, 95, 16, 0, 0, 'all_opponents', 1, '相手全体が対象。100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(549, 'くろいきり', 'こおり', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, 'すべてのポケモンの能力ランクの変化を元に戻す。'),
(551, 'ボディプレス', 'かくとう', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '『こうげき』ではなく、自分の『ぼうぎょ』と『ぼうぎょ』ランクを『こうげき』の数値にしてダメージ計算する。'),
(554, 'はどうだん', 'かくとう', 'special', '特殊', 80, NULL, 20, 0, 0, 'single', 0, '自分の命中率、相手の回避率に関係なく必ず命中する。'),
(555, 'しねんのずつき', 'エスパー', 'physical', '物理', 80, 90, 16, 0, 1, 'single', 0, '20%の確率で相手をひるませる。'),
(556, 'ミラーコート', 'エスパー', 'special', '特殊', NULL, 100, 20, 0, 0, 'single', 0, '相手の特殊攻撃のダメージの2倍をその相手に与える。『ダブルバトル』の時は最後に受けた技のみ有効になる。必ず後攻になる(優先度:-5)。『あく』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(563, 'あくのはどう', 'あく', 'special', '特殊', 80, 100, 16, 0, 0, 'single', 0, '20%の確率で相手をひるませる。'),
(565, 'アイアンヘッド', 'はがね', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '20%の確率で相手をひるませる。'),
(566, 'ジャイロボール', 'はがね', 'physical', '物理', NULL, 100, 8, 0, 1, 'single', 0, '相手より『すばやさ』が低いほど威力が高くなる。(25×相手のすばやさ÷自分のすばやさ)+1が威力になる。ただし最大威力は150。小数点以下は切り捨て。'),
(567, 'ラスターカノン', 'はがね', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(568, 'てっぺき', 'はがね', 'status', '変化', NULL, NULL, 16, 0, 0, 'self', 0, '自分の『ぼうぎょ』ランクを2段階上げる。'),
(579, 'ねっとう', 'みず', 'special', '特殊', 80, 100, 16, 0, 0, 'single', 0, '30%の確率で相手を『やけど』状態にする。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。また、相手の『こおり』状態を治す。'),
(671, 'ダブルアタック', 'ノーマル', 'physical', '物理', 35, 90, 12, 0, 1, 'single', 0, '1ターンに2回連続で攻撃する。'),
(672, 'がむしゃら', 'ノーマル', 'physical', '物理', NULL, 100, 8, 0, 1, 'single', 0, '相手の残りHPから自分の残りHPを引いた分のダメージを与える。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(676, 'バトンタッチ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '他の味方のポケモンと交代し、かかっていた補助効果を引き継ぐ。'),
(682, 'きあいだめ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '『きゅうしょアップ』状態(急所ランク2段階)となり、今後自分の技が急所に当たりやすくなる。(すでに『きゅうしょアップ』状態の時は失敗する)'),
(683, 'いやなおと', 'ノーマル', 'status', '変化', NULL, 85, 20, 0, 0, 'single', 0, '相手の『ぼうぎょ』ランクを2段階下げる。音系の技。相手の『みがわり』状態を貫通する。'),
(688, 'エレキネット', 'でんき', 'special', '特殊', 55, 95, 16, 0, 0, 'all_opponents', 1, '相手全体が対象。100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(689, 'とびかかる', 'むし', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '100%の確率で相手の『こうげき』ランクを1段階下げる。'),
(690, 'シザークロス', 'むし', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '通常攻撃。'),
(691, 'はいよるいちげき', 'むし', 'physical', '物理', 70, 90, 12, 0, 1, 'single', 0, '100%の確率で、相手の『とくこう』ランクを1段階下げる'),
(692, 'とんぼがえり', 'むし', 'physical', '物理', 70, 100, 20, 0, 1, 'single', 0, '攻撃後、手持ちのポケモンと入れ替わる。'),
(693, 'むしくい', 'むし', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '相手が持っているバトルに効果のある『きのみ』を奪って、自分に使う。'),
(694, 'とびつく', 'むし', 'physical', '物理', 50, 100, 20, 0, 1, 'single', 0, '100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(695, 'とどめばり', 'むし', 'physical', '物理', 50, 100, 20, 0, 1, 'single', 0, 'この技で相手を倒すと、自分の『こうげき』ランクが3段階上がる。'),
(696, 'ミサイルばり', 'むし', 'physical', '物理', 25, 95, 20, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(697, 'かふんだんご', 'むし', 'special', '特殊', 90, 100, 16, 0, 0, 'single', 0, '味方に使った場合、ダメージではなく味方のHPを最大HPの1/2回復する。'),
(698, 'むしのさざめき', 'むし', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。音系の技。相手の『みがわり』状態を貫通する。'),
(705, 'クロスポイズン', 'どく', 'physical', '物理', 70, 100, 20, 0, 1, 'single', 0, '10%の確率で相手を『どく』状態にする。急所に当たりやすい(急所ランク:+1)。'),
(708, 'どくびし', 'どく', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '相手の場を『どくびし』状態にし、相手はポケモンを交代する度に、出したポケモンが『どく』状態になる。2回使うと『もうどく』状態になる。『どく』『はがね』『ひこう』タイプ、特性『ふゆう』のポケモンは効果を受けない。『どく』タイプのポケモンが出ると効果がなくなる。'),
(710, 'ドリルライナー', 'じめん', 'physical', '物理', 80, 95, 12, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(713, 'こうそくいどう', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『すばやさ』ランクが2段階上がる。'),
(714, 'じごくづき', 'あく', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '相手は2ターンの間、音系の技『いにしえのうた』『いびき』『いやしのすず』『いやなおと』『うたう』『うたかたのアリア』『エコーボイス』『おしゃべり』『おたけび』『きんぞくおん』『くさぶえ』『さわぐ』『スケイルノイズ』『すてゼリフ』『チャームボイス』『ちょうおんぱ』『とおぼえ』『ないしょばなし』『なきごえ』『バークアウト』『ハイパーボイス』『ばくおんぱ』『ほえる』『ほろびのうた』『むしのさざめき』『りんしょう』『ソウルビート』『オーバードライブ』『ぶきみなじゅもん』『フレアソング』『みわくのボイス』『サイコノイズ』を使えなくなる。'),
(717, 'ダメおし', 'あく', 'physical', '物理', 60, 100, 12, 0, 1, 'single', 0, 'そのターン、相手が既にダメージを受けている時、威力が2倍になる。'),
(718, 'どろぼう', 'あく', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '相手が持っている道具を自分の物にする。自分が既に道具を持っている場合は失敗するが、技『はたきおとす』で自分の道具が無効化されている時は奪う事ができ、道具は上書きされる。トレーナー戦の場合はバトル終了後になくなる。'),
(719, 'しっぺがえし', 'あく', 'physical', '物理', 50, 100, 12, 0, 1, 'single', 0, '自分が後攻の時、威力が2倍になる。'),
(729, 'むしのていこう', 'むし', 'special', '特殊', 50, 100, 20, 0, 0, 'all_opponents', 1, '相手全体が対象。100%の確率で相手の『とくこう』ランクを1段階下げる。'),
(730, 'まとわりつく', 'むし', 'special', '特殊', 20, 100, 20, 0, 1, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(798, 'でんこうせっか', 'ノーマル', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。'),
(800, 'さわぐ', 'ノーマル', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '3ターン連続で攻撃し、その間はすべてのポケモンが『ねむり』状態にならない。音系の技。相手の『みがわり』状態を貫通する。'),
(808, 'ふきとばし', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '必ず後攻になる(優先度:-6)。相手のポケモンを強制的に交代させる。野生のポケモンの場合は戦闘を終了する。自分の命中率、相手の回避率に関係なく必ず命中する。相手の『まもる』『みきり』『トーチカ』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』の効果を受けない。相手の『みがわり』状態を貫通する。ダイマックスしている相手には無効。野生のポケモンの場合、相手が自分のレベルより高い場合は失敗する。'),
(813, 'ゴッドバード', 'ひこう', 'physical', '物理', 140, 90, 8, 0, 0, 'single', 0, '1ターン目は攻撃せずに、2ターン目で攻撃する。30%の確率で相手をひるませる。急所に当たりやすい(急所ランク:+1)。'),
(814, 'ブレイブバード', 'ひこう', 'physical', '物理', 120, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。'),
(822, 'フェザーダンス', 'ひこう', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手の『こうげき』ランクを2段階下げる。'),
(833, 'みきり', 'かくとう', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '必ず先制でき(優先度:+4)、そのターンの間、相手の技を受けない。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。ダイマックス技や第7世代のZワザの攻撃技は貫通し、1/4のダメージを受ける。'),
(835, 'ついばむ', 'ひこう', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '相手が持っているバトルに効果のある『きのみ』を奪って、自分に使う。');
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(884, 'まきつく', 'ノーマル', 'physical', '物理', 15, 90, 20, 0, 1, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(888, 'はきだす', 'ノーマル', 'special', '特殊', NULL, 100, 12, 0, 0, 'single', 0, '技『たくわえる』を使った数だけ威力が高くなる。1つの時は100、2つの時は200、3つの時は300になる。技『たくわえる』で上がった『ぼうぎょ』『とくぼう』ランクは元に戻る。技『たくわえる』を使っていない時は失敗する。'),
(889, 'のみこむ', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '技『たくわえる』を使った数だけHPが多く回復する。1つの時は最大HPの1/4、2つの時は最大HPの1/2、3つの時は全回復する。技『たくわえる』で上がった『ぼうぎょ』『とくぼう』ランクは元に戻る。技『たくわえる』を使っていない時は失敗する。'),
(890, 'たくわえる', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『ぼうぎょ』『とくぼう』ランクを1段階ずつ上げる。技『のみこむ』『はきだす』の効果を上げる。3回までたくわえることができる。'),
(891, 'いたみわけ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '自分と相手のHPを2匹の残りHPの平均値にする(足して2で割る)。ダイマックス時は、もとのHPで平均値を計算して、もとのHPと平均値との差分値を現在のダイマックス時のHPから増減する。'),
(897, 'へびにらみ', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手を『まひ』状態にする。『でんき』タイプには無効。'),
(905, 'かみなりのキバ', 'でんき', 'physical', '物理', 65, 95, 16, 0, 1, 'single', 0, '10%の確率で相手を『まひ』状態にする。10%の確率で、相手をひるませる。'),
(906, 'きゅうけつ', 'むし', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの半分だけ自分のHPが回復する。'),
(910, 'ダストシュート', 'どく', 'physical', '物理', 120, 80, 8, 0, 0, 'single', 0, '30%の確率で相手を『どく』状態にする。'),
(912, 'どくどくのキバ', 'どく', 'physical', '物理', 50, 100, 16, 0, 1, 'single', 0, '50%の確率で相手を『もうどく』状態にする。『もうどく』状態は通常の『どく』状態と違い、受けるダメージが1/16、2/16、3/16・・・と増えていく。交代すると改めて1/16からになる。'),
(913, 'ゲップ', 'どく', 'special', '特殊', 120, 90, 12, 0, 0, 'single', 0, 'この技は『きのみ』を食べると使えるようになる。'),
(918, 'とぐろをまく', 'どく', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『こうげき』『ぼうぎょ』『命中率』ランクが1段階ずつ上がる。'),
(920, 'いえき', 'どく', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手の特性を無効にする。ただし、『バトルスイッチ』『ばけのかわ』などフォルムに関わる特性や、一部の固有の特性などには効かない。'),
(928, 'こおりのキバ', 'こおり', 'physical', '物理', 65, 95, 16, 0, 1, 'single', 0, '10%の確率で相手を『こおり』状態にする。10%の確率で、相手をひるませる。'),
(930, 'サイコファング', 'エスパー', 'physical', '物理', 85, 100, 12, 0, 1, 'single', 0, '相手の技『リフレクター』『ひかりのかべ』『オーロラベール』を解除して攻撃する。'),
(932, 'うらみ', 'ゴースト', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手の最後に使った技のPPを4減らす。'),
(938, 'うっぷんばらし', 'あく', 'physical', '物理', 75, 100, 8, 0, 1, 'single', 0, 'そのターンの間に自分の能力ランクを下げられていると、威力が2倍になる(通常は後攻で攻撃する必要があるが、場に出た時に能力ランクを下げられた場合も対象となる)。'),
(939, 'ふいうち', 'あく', 'physical', '物理', 70, 100, 8, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。そのターン相手が選んだ技が攻撃技ではない場合や、優先度などの関係ですでに攻撃を終えていた場合は失敗する。相手が『ねむり』『こおり』状態でも攻撃技を選択していれば成功する。'),
(947, 'バークアウト', 'あく', 'special', '特殊', 55, 95, 16, 0, 0, 'all_opponents', 1, '相手全体が対象。100%の確率で相手の『とくこう』ランクを1段階下げる。音系の技。相手の『みがわり』状態を貫通する。'),
(948, 'すりかえ', 'あく', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手と自分が持っている道具を入れ替える。片方しか道具を持っていない場合も成功する。'),
(955, 'いちゃもん', 'あく', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '使用後、相手は同じ技を連続で出せなくなる。ダイマックスしている相手には無効。'),
(957, 'かなしばり', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手が最後に使った技を4ターンの間使えなくする。'),
(965, 'フェイント', 'ノーマル', 'physical', '物理', 30, 100, 12, 0, 0, 'single', 0, '必ず先制できる(優先度:+2)。相手が技『まもる』『みきり』『たたみがえし』『トーチカ』『キングシールド』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』『ファストガード』『ワイドガード』をしている場合は、その効果を解除して攻撃できる(使用していない場合は通常攻撃)。『ダイウォール』は解除はできないが、貫通する。'),
(970, 'くすぐる', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『こうげき』『ぼうぎょ』ランクを1段階ずつ下げる。'),
(971, 'ねがいごと', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '次のターンの終了時にHPが最大HPの半分回復する。交代した場合は同じ位置にいるポケモンが回復する。'),
(973, 'アンコール', 'ノーマル', 'status', '変化', NULL, 100, 8, 0, 0, 'single', 0, '3ターンの間、相手は最後に使用した技しか使えなくなる。ただし、PPが0になると解除される。相手の技が『ものまね』『ゆびをふる』『オウムがえし』『へんしん』『わるあがき』『スケッチ』『ねごと』『アンコール』『しぜんのちから』『ねこのて』『さきどり』『まねっこ』『ダイマックスほう』『バーンアクセル』『ダークアクセル』『ポイズンアクセル』『ファイトアクセル』『マジカルアクセル』の場合は失敗する。ダイマックスしているポケモンには無効。なお、ダイマックス技や第7世代のZワザは影響を受けずに使うことができる。'),
(983, 'ボルテッカー', 'でんき', 'physical', '物理', 120, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。10%の確率で相手を『まひ』状態にする。'),
(984, 'ワイルドボルト', 'でんき', 'physical', '物理', 90, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの1/4を自分も受ける。'),
(986, 'ほっぺすりすり', 'でんき', 'physical', '物理', 20, 100, 20, 0, 1, 'single', 0, '100%の確率で相手を『まひ』状態にする。'),
(987, 'でんじほう', 'でんき', 'special', '特殊', 120, 50, 8, 0, 0, 'single', 0, '100%の確率で相手を『まひ』状態にする。'),
(988, 'かみなり', 'でんき', 'special', '特殊', 110, 70, 12, 0, 0, 'single', 0, '30%の確率で相手を『まひ』状態にする。天気が『あめ』の時は必ず命中し、『にほんばれ』の時は命中率が50%になる。相手が技『そらをとぶ』『とびはねる』『フリーフォール』を使っている時でも命中する。'),
(989, '10まんボルト', 'でんき', 'special', '特殊', 90, 100, 16, 0, 0, 'single', 0, '10%の確率で相手を『まひ』状態にする。'),
(990, 'ほうでん', 'でんき', 'special', '特殊', 80, 100, 16, 0, 0, 'all_except_self', 1, '自分以外全員が対象。30%の確率で相手を『まひ』状態にする。'),
(991, 'ライジングボルト', 'でんき', 'special', '特殊', 70, 100, 20, 0, 0, 'single', 0, '場の状態が『エレキフィールド』で、なおかつ相手が『ひこう』タイプや特性『ふゆう』などではなく地面にいる時、威力が2倍になる(自分も地面にいれば、フィールドの1.3倍の効果もさらに加わる)。'),
(992, 'ボルトチェンジ', 'でんき', 'special', '特殊', 70, 100, 20, 0, 0, 'single', 0, '攻撃後、手持ちのポケモンと入れ替わる。'),
(994, 'チャージビーム', 'でんき', 'special', '特殊', 50, 90, 12, 0, 0, 'single', 0, '70%の確率で自分の『とくこう』ランクが1段階上がる。'),
(995, 'エレキボール', 'でんき', 'special', '特殊', NULL, 100, 12, 0, 0, 'single', 0, '相手より『すばやさ』が高いほど威力が高くなる。1倍未満は40、2倍未満は60、3倍未満は80、4倍未満は120、それ以上は150。'),
(996, 'エレキフィールド', 'でんき', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、場の状態を『エレキフィールド』にする。『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、『ねむり』『ねむけ』(『あくび』)状態にならず、また『でんき』タイプの技の威力が1.3倍になる(第7世代までは1.5倍)。すでに『ねむり』状態の場合は回復しない。また、道具『エレキシード』を持ったポケモンは『ぼうぎょ』ランクが1段階上がる(この効果は、地面にいないポケモンでも発動する)。'),
(997, 'かいでんぱ', 'でんき', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手の『とくこう』ランクを2段階下げる。'),
(998, 'じゅうでん', 'でんき', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, 'でんき威力アップ状態になり、一度だけ次回使う自分の『でんき』タイプの技の威力が2倍になる(第8世代までは次のターンまでだけ)。また、自分の『とくぼう』ランクが1段階上がる。'),
(999, 'でんじは', 'でんき', 'status', '変化', NULL, 90, 20, 0, 0, 'single', 0, '相手を『まひ』状態にする。『じめん』タイプや『でんき』タイプには無効。'),
(1003, 'はやてがえし', 'かくとう', 'physical', '物理', 65, 100, 16, 0, 1, 'single', 0, '必ず先制できる(優先度:+3)。相手を100%の確率でひるませる。ただし、そのターン相手が選んだ技が先制技ではない場合や、すでに攻撃を終えていた場合は失敗する。'),
(1004, 'きしかいせい', 'かくとう', 'physical', '物理', NULL, 100, 16, 0, 1, 'single', 0, '自分の残りHPが少ないほど威力が高くなる。(威力は20～200)'),
(1012, 'わるだくみ', 'あく', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『とくこう』ランクを2段階上げる。'),
(1013, 'うそなき', 'あく', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『とくぼう』ランクを2段階下げる。'),
(1015, 'じゃれつく', 'フェアリー', 'physical', '物理', 90, 90, 12, 0, 1, 'single', 0, '10%の確率で相手の『こうげき』ランクを1段階下げる。'),
(1016, 'みわくのボイス', 'フェアリー', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '100%の確率で、そのターンの間に能力ランクが上がった相手ポケモンを1～4ターンの間『こんらん』状態にする(通常は後攻で攻撃する必要があるが、場に出た時に能力ランクが上がった場合も対象となる)。音系の技。相手の『みがわり』状態を貫通する。'),
(1017, 'ドレインキッス', 'フェアリー', 'special', '特殊', 50, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの3/4だけ自分のHPが回復する。'),
(1019, 'てんしのキッス', 'フェアリー', 'status', '変化', NULL, 75, 12, 0, 0, 'single', 0, '相手を1～4ターンの間『こんらん』状態にする。'),
(1030, 'めいそう', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『とくこう』『とくぼう』ランクが1段階ずつ上がる。'),
(1032, 'ほしがる', 'ノーマル', 'physical', '物理', 60, 100, 20, 0, 1, 'single', 0, '相手が持っている道具を自分の物にする。自分が既に道具を持っている場合は失敗するが、技『はたきおとす』で自分の道具が無効化されている時は奪う事ができ、道具は上書きされる。トレーナー戦の場合はバトル終了後になくなる。'),
(1033, 'でんじふゆう', 'でんき', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '5ターンの間、『ふゆう』と同じ『でんじふゆう』状態となり、『じめん』タイプの技や、『まきびし』『どくびし』『ねばねばネット』、『グラスフィールド』『ミストフィールド』『エレキフィールド』『サイコフィールド』などの効果を受けなくなる。'),
(1034, 'つぶらなひとみ', 'フェアリー', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+1)。相手の『こうげき』ランクを1段階下げる。'),
(1079, 'ドレインパンチ', 'かくとう', 'physical', '物理', 75, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの半分だけ自分のHPが回復する。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(1097, 'マジカルシャイン', 'フェアリー', 'special', '特殊', 80, 100, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。通常攻撃。'),
(1113, 'スピードスワップ', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の『すばやさ』を入れ替える。'),
(1166, 'サイコキネシス', 'エスパー', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '10%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(1167, 'ワイドフォース', 'エスパー', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '場の状態が『サイコフィールド』で、自分が『ひこう』タイプや特性『ふゆう』などではなく地面にいる時、威力が1.5倍になり(フィールドの1.3倍の効果もさらに加わる)、また相手全体を攻撃する(その時ダブルバトルではダメージは0.75倍)。'),
(1168, 'サイコショック', 'エスパー', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '相手の『とくぼう』ではなく、相手の『ぼうぎょ』の能力値でダメージ計算する。'),
(1169, 'サイコノイズ', 'エスパー', 'special', '特殊', 75, 100, 12, 0, 0, 'single', 0, '100%の確率で、相手は2ターンの間『かいふくふうじ』状態となり、回復系の技『あさのひざし』『いやしのねがい』『いやしのはどう』『ウッドホーン』『かいふくしれい』『ギガドレイン』『きゅうけつ』『こうごうせい』『じこさいせい』『じょうか』『すいとる』『すなあつめ』『タマゴうみ』『ちからをすいとる』『つきのひかり』『デスウイング』『ドレインキッス』『ドレインパンチ』『なまける』『ねがいごと』『ねむる』『のみこむ』『はねやすめ』『パラボラチャージ』『フラワーヒール』『みかづきのまい』『ミルクのみ』『メガドレイン』『ゆめくい』『いのちのしずく』『ジャングルヒール』『みかづきのいのり』『さいきのいのり』『むねんのつるぎ』『シャカシャカほう』が使えなくなり、また特性や道具、場の状態などでHPが回復しなくなる。音系の技。相手の『みがわり』状態を貫通する。'),
(1170, 'アシストパワー', 'エスパー', 'special', '特殊', 20, 100, 12, 0, 0, 'single', 0, '自分のいずれかの能力ランクが1つ上がる度に威力が20上がる。'),
(1172, 'サイコフィールド', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、場の状態を『サイコフィールド』にする。『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、相手(味方は含まない)の先制技を受けなくなり、また『エスパー』タイプの技の威力が1.3倍になる(第7世代までは1.5倍)。また、道具『サイコシード』を持ったポケモンは『とくぼう』ランクが1段階上がる(この効果は、地面にいないポケモンでも発動する)。'),
(1173, 'マジックルーム', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、すべてのポケモンの道具の効果がなくなる。'),
(1175, 'スキルスワップ', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の特性を入れ替える。ただし、『ふしぎなまもり』など一部の固有な特性は入れ替えられない。ダイマックスしている相手には無効。'),
(1203, 'みらいよち', 'エスパー', 'special', '特殊', 120, 100, 12, 0, 0, 'single', 0, '2ターン後に攻撃する。交代した場合は同じ位置にいるポケモンに攻撃する。タイプ相性の影響を受ける。'),
(1204, 'サイドチェンジ', 'エスパー', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '必ず先制できる(優先度:+2)。自分と味方1体の位置を交代する。ダブルバトル用。第9世代からは、連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。'),
(1209, 'リサイクル', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分が最後に使用した持ち物の道具を手に入れる。道具を持っている場合は失敗する。'),
(1216, 'ハイパーボイス', 'ノーマル', 'special', '特殊', 90, 100, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。音系の技。相手の『みがわり』状態を貫通する。'),
(1218, 'トライアタック', 'ノーマル', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '20%の確率で相手を『まひ』『やけど』『こおり』状態のうちの1つにする。どの状態異常になるかはランダム。'),
(1221, 'おさきにどうぞ', 'ノーマル', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '相手は『すばやさ』に関係なく、この技を受けた直後に行動できるようになる。ダブルバトル用。'),
(1222, 'まねっこ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '最後に使われた技で相手に攻撃する。自分の技も対象となる。最後の技がダイマックス技の場合、元となった技が使われる。'),
(1226, 'このゆびとまれ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+2)。そのターンの相手の技をすべて自分が受ける。ただし、全体技には効果がない。ダブルバトル用。'),
(1227, 'じこあんじ', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '相手の能力ランクの変化を、すべて自分にコピーする。'),
(1235, 'うたう', 'ノーマル', 'status', '変化', NULL, 55, 16, 0, 0, 'single', 0, '相手を『ねむり』状態にする。音系の技。相手の『みがわり』状態を貫通する。'),
(1252, 'とびはねる', 'ひこう', 'physical', '物理', 85, 85, 8, 0, 1, 'single', 0, '1ターン目に空中へ飛び上がり、2ターン目に攻撃する。空中にいる間は『うちおとす』『かぜおこし』『かみなり』『サウザンアロー』『スカイアッパー』『たつまき』『ぼうふう』以外の技を受けない。30%の確率で相手を『まひ』状態にする。'),
(1255, 'メテオビーム', 'いわ', 'special', '特殊', 120, 90, 12, 0, 0, 'single', 0, '1ターン目に100%の確率で自分の『とくこう』ランクを1段階上げ、2ターン目で攻撃する。'),
(1256, 'ステルスロック', 'いわ', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '使用後、相手はポケモンを交代する度に、出てきたポケモンは最大HPの1/8のダメージを受ける。『タイプ』相性の影響を受け、例えば4倍弱点の場合は最大HPの1/2のダメージとなる。'),
(1271, 'いやしのはどう', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '相手は最大HPの1/2回復する。(ダブルバトルで味方に使うと良い)'),
(1272, 'ワンダールーム', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、すべてのポケモンの『ぼうぎょ』と『とくぼう』の能力値が入れ替わる。もう1度使用すると元に戻る。'),
(1273, 'いやしのねがい', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分が『ひんし』になる代わりに、次に出す自分のポケモンの状態異常とHPが全回復する。(『みかづきのまい』と異なりPPは回復しない)'),
(1274, 'じゅうりょく', 'エスパー', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、すべてのポケモンの命中率が5/3倍(約1.67倍、1.6倍の説もあり)になる。また、特性『ふゆう』や、『ひこう』タイプのポケモンに『じめん』タイプの技が当たるようになる。技『そらをとぶ』『はねる』『とびげり』『とびひざげり』『とびはねる』『でんじふゆう』『フライングプレス』『フリーフォール』が使えなくなり、使用している場合は解除される。『テレキネシス』を受けなくなり、受けている場合は解除される。技『Gのちから』の威力が1.5倍になる。'),
(1276, 'コスモパワー', 'エスパー', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『ぼうぎょ』『とくぼう』ランクが1段階ずつ上がる。'),
(1277, 'ふういん', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分が『ふういん』状態になり、自分が場を離れるまで、自分が覚えている技と同じ技を相手のポケモンは使えなくなる。'),
(1279, 'トリック', 'エスパー', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手と自分が持っている道具を入れ替える。片方しか道具を持っていない場合も成功する。'),
(1284, 'シャドーボール', 'ゴースト', 'special', '特殊', 80, 100, 16, 0, 0, 'single', 0, '20%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(1285, 'ナイトヘッド', 'ゴースト', 'special', '特殊', NULL, 100, 16, 0, 0, 'single', 0, '自分のレベルと同じ値の固定ダメージを与える。『ノーマル』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(1290, 'コメットパンチ', 'はがね', 'physical', '物理', 90, 90, 12, 0, 1, 'single', 0, '20%の確率で自分の『こうげき』ランクが1段階上がる。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(1292, 'ミストバースト', 'フェアリー', 'special', '特殊', 100, 100, 8, 0, 0, 'all_except_self', 1, '自分以外全員が対象。攻撃後、自分が『ひんし』状態になる。場の状態が『ミストフィールド』で、自分が『ひこう』タイプや特性『ふゆう』などではなく地面にいる時、威力が1.5倍になる。'),
(1293, 'ムーンフォース', 'フェアリー', 'special', '特殊', 95, 100, 16, 0, 0, 'single', 0, '10%の確率で相手の『とくこう』ランクを1段階下げる。'),
(1297, 'ミストフィールド', 'フェアリー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '5ターンの間、場の状態を『ミストフィールド』にする。『ひこう』タイプや特性『ふゆう』などではない地面にいるすべてのポケモンは、状態異常にならず、また『ドラゴン』タイプの技の威力が半減する。すでに状態異常の場合は回復しない。また、道具『ミストシード』を持ったポケモンは『とくぼう』ランクが1段階上がる(この効果は、地面にいないポケモンでも発動する)。'),
(1298, 'つきのひかり', 'フェアリー', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが、天気が通常の時は最大HPの1/2、『にほんばれ』の時は最大HPの2/3、『あめ』『ゆき』『すなあらし』の時は最大HPの1/4回復する。'),
(1301, 'はたく', 'ノーマル', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '通常攻撃。'),
(1302, 'ちいさくなる', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の回避率を2段階上げる。ただし、技『サンダーダイブ』『のしかかり』『ふみつけ』『ドラゴンダイブ』『ハードローラー』『ハイパーダーククラッシャー』『フライングプレス』『ヒートスタンプ』『ヘビーボンバー』は必ず命中し威力2倍で受けるようになってしまう(ヒートスタンプは第6世代以降、ヘビーボンバーは第7世代以降。なお、ゴーストダイブは第6世代のみ)。'),
(1321, 'いやしのすず', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '自分と味方全体のポケモンの状態異常を治す。音系の技。味方が『みがわり』状態でも効果が発生する。この技は『ダイウォール』の効果も受けない。'),
(1322, 'なりきり', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の特性を相手の特性と同じにする。ただし、『ふしぎなまもり』など一部の固有な特性はコピーできない。'),
(1323, 'とっておき', 'ノーマル', 'physical', '物理', 140, 100, 8, 0, 1, 'single', 0, 'この技は自分の持っている他の技をすべて使うと使えるようになる。'),
(1443, 'スイープビンタ', 'ノーマル', 'physical', '物理', 25, 85, 12, 0, 1, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(1449, 'とおぼえ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '自分と味方全体の『こうげき』ランクを1段階ずつ上げる(第7世代までは、対象は自分のみ)。第8世代からは、音系の技。この技は『ダイウォール』の効果も受けない。'),
(1473, 'しっとのほのお', 'ほのお', 'special', '特殊', 70, 100, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。100%の確率で、そのターンの間に能力ランクが上がった相手ポケモンを『やけど』状態にする(通常は後攻で攻撃する必要があるが、場に出た時に能力ランクが上がった場合も対象となる)。'),
(1481, 'じんつうりき', 'エスパー', 'special', '特殊', 80, 100, 20, 0, 0, 'single', 0, '10%の確率で相手をひるませる。');
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(1483, 'パワースワップ', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の『こうげき』『とくこう』ランクを入れ替える。'),
(1489, 'さいみんじゅつ', 'エスパー', 'status', '変化', NULL, 60, 20, 0, 0, 'single', 0, '相手を『ねむり』状態にする。'),
(1491, 'たたりめ', 'ゴースト', 'special', '特殊', 65, 100, 12, 0, 0, 'single', 0, '相手が状態異常の時、威力が2倍になる。'),
(1494, 'あやしいひかり', 'ゴースト', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '相手を1～4ターンの間『こんらん』状態にする。'),
(1495, 'イカサマ', 'あく', 'physical', '物理', 95, 100, 16, 0, 1, 'single', 0, '自分の『こうげき』ではなく、相手の『こうげき』の能力値でダメージ計算する。'),
(1501, 'おきみやげ', 'あく', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, '自分が『ひんし』になる代わりに、相手の『こうげき』『とくこう』ランクを2段階ずつ下げる。'),
(1540, 'こおりのつぶて', 'こおり', 'physical', '物理', 40, 100, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+1)。'),
(1541, 'つららばり', 'こおり', 'physical', '物理', 25, 100, 20, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(1542, 'トリプルアクセル', 'こおり', 'physical', '物理', 20, 90, 12, 0, 1, 'single', 0, '1ターンに外れるまで最大3回連続で攻撃する。攻撃が当たる度に威力が20ずつ増える。'),
(1545, 'フリーズドライ', 'こおり', 'special', '特殊', 70, 100, 20, 0, 0, 'single', 0, 'この技は『みず』タイプにも効果抜群になる。ポケモンSVまでは、さらに10%の確率で相手を『こおり』状態にする。'),
(1547, 'ゆきげしき', 'こおり', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、天気を『ゆき』にする(『こおり』タイプのポケモンは、『ぼうぎょ』が1.5倍になる)。'),
(1548, 'オーロラベール', 'こおり', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '天気が『ゆき』状態の時のみ使用でき、5ターンの間、自分と味方が受ける相手の物理攻撃と特殊攻撃のダメージを半分にする。味方が複数の場合は半分ではなく2/3になる。急所に当たった場合は軽減されない。交代しても効果は続く。'),
(1577, 'ぜったいれいど', 'こおり', 'special', '特殊', NULL, 30, 8, 0, 0, 'single', 0, '相手を『ひんし』状態にする。相手が『こおり』タイプの場合は効果がない。また、『こおり』タイプ以外のポケモンが使うと命中率が20%に下がる。ダイマックスしている相手には無効。'),
(1583, 'こおりのいぶき', 'こおり', 'special', '特殊', 60, 90, 12, 0, 0, 'single', 0, '必ず急所に当たる。'),
(1592, 'あばれる', 'ノーマル', 'physical', '物理', 120, 100, 12, 0, 1, 'single', 0, '自分は『あばれ』状態となり、2～3ターン連続で攻撃し、他の行動はできない。その後1～4ターンの間『こんらん』状態になる。'),
(1594, 'しんそく', 'ノーマル', 'physical', '物理', 80, 100, 8, 0, 1, 'single', 0, '必ず先制できる(優先度:+2)。'),
(1603, 'あさのひざし', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが、天気が通常の時は最大HPの1/2、『にほんばれ』の時は最大HPの2/3、『あめ』『ゆき』『すなあらし』の時は最大HPの1/4回復する。'),
(1611, 'だいふんげき', 'ほのお', 'physical', '物理', 120, 100, 12, 0, 0, 'single', 0, '自分は『あばれ』状態となり、2～3ターン連続で攻撃し、他の行動はできない。その後1～4ターンの間『こんらん』状態になる。'),
(1617, 'もえつきる', 'ほのお', 'special', '特殊', 130, 100, 8, 0, 0, 'single', 0, '攻撃後、自分は『ほのお』タイプではなくなる。自分が『ほのお』タイプではない時は失敗する。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。'),
(1631, 'インファイト', 'かくとう', 'physical', '物理', 120, 100, 8, 0, 1, 'single', 0, '攻撃後、自分の『ぼうぎょ』『とくぼう』ランクが1段階ずつ下がる。'),
(1653, 'ばかぢから', 'かくとう', 'physical', '物理', 120, 100, 8, 0, 1, 'single', 0, '攻撃後、自分の『こうげき』『ぼうぎょ』ランクが1段階ずつ下がる。'),
(1693, 'もろはのずつき', 'いわ', 'physical', '物理', 150, 80, 8, 0, 1, 'single', 0, '相手に与えたダメージの1/2を自分も受ける。'),
(1694, 'ストーンエッジ', 'いわ', 'physical', '物理', 100, 80, 8, 0, 0, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(1698, 'ロックブラスト', 'いわ', 'physical', '物理', 25, 90, 12, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(1699, 'パワージェム', 'いわ', 'special', '特殊', 80, 100, 20, 0, 0, 'single', 0, '通常攻撃。'),
(1718, 'スマートホーン', 'はがね', 'physical', '物理', 70, NULL, 12, 0, 1, 'single', 0, '自分の命中率、相手の回避率に関係なく必ず命中する。'),
(1735, 'じこさいせい', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが最大HPの半分回復する。'),
(1749, 'サイコカッター', 'エスパー', 'physical', '物理', 70, 100, 20, 0, 0, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(1760, 'ガードシェア', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の『ぼうぎょ』と『とくぼう』の数値をそれぞれ足して、互いに半分ずつに分ける。'),
(1761, 'トリックルーム', 'エスパー', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '5ターンの間、『すばやさ』が低いポケモンから攻撃できるようになる。ただし、必ず先制できる技には無効。もう1度使用すると元に戻る。必ず後攻になる(優先度:-7)。'),
(1762, 'ガードスワップ', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の『ぼうぎょ』『とくぼう』ランクを入れ替える。'),
(1777, 'ちょうはつ', 'あく', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '3ターンの間、相手は攻撃技しか出せなくなる。(変化技を使えなくする)'),
(1797, 'パワートリック', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の『こうげき』と『ぼうぎょ』を入れ替える。『ランク』は変化しない。'),
(1906, 'ワイドガード', 'いわ', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '必ず先制でき(優先度:+3)、そのターンの間、自分と味方は相手や味方が使った複数のポケモンが対象の技を受けない。'),
(1910, '10まんばりき', 'じめん', 'physical', '物理', 95, 95, 12, 0, 1, 'single', 0, '通常攻撃。'),
(1917, 'クロスチョップ', 'かくとう', 'physical', '物理', 100, 80, 8, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(1921, 'ローキック', 'かくとう', 'physical', '物理', 65, 100, 20, 0, 1, 'single', 0, '100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(1922, 'やまあらし', 'かくとう', 'physical', '物理', 60, 100, 12, 0, 1, 'single', 0, '必ず急所に当たる。'),
(1926, 'けたぐり', 'かくとう', 'physical', '物理', NULL, 100, 20, 0, 1, 'single', 0, '相手の『おもさ』が重いほど威力が高くなる。10kg未満は20、25kg未満は40、50kg未満は60、100kg未満は80、200kg未満は100、それ以上は120。ダイマックスしている相手には無効。'),
(1928, 'コーチング', 'かくとう', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分を除く味方全体の『こうげき』『ぼうぎょ』ランクが1段階ずつ上がる(ダブルバトル用)。この技は『ダイウォール』の効果も受けない。'),
(1929, 'ファストガード', 'かくとう', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '必ず先制でき(優先度:+3)、そのターンの間、自分と味方は相手の先制攻撃の技を受けない。特性の効果による先制攻撃も受けない。'),
(1930, 'ビルドアップ', 'かくとう', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『こうげき』『ぼうぎょ』ランクを1段階ずつ上げる。'),
(1934, 'DDラリアット', 'あく', 'physical', '物理', 85, 100, 12, 0, 1, 'single', 0, '相手の能力ランクの変化に関係なく、ダメージを与える。'),
(1942, 'バレットパンチ', 'はがね', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(1943, 'ヘビーボンバー', 'はがね', 'physical', '物理', NULL, 100, 12, 0, 1, 'single', 0, '自分の『おもさ』が相手より重いほど威力が高くなる。相手の『おもさ』が自分の1/5以下なら120、1/4以下なら100、1/3以下なら80、1/2以下なら60、それより大きければ40。相手が技『ちいさくなる』を使用していると必ず命中し、威力が2倍になる(第7世代以降)。ダイマックスしている相手には無効。'),
(1944, 'マッハパンチ', 'かくとう', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(1956, 'しんくうは', 'かくとう', 'special', '特殊', 40, 100, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+1)。'),
(1978, 'リーフブレード', 'くさ', 'physical', '物理', 90, 100, 16, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(1988, 'ちからをすいとる', 'くさ', 'status', '変化', NULL, 100, 8, 0, 0, 'single', 0, '相手の『こうげき』の能力値と同じ値だけ自分のHPを回復し、相手の『こうげき』ランクを1段階下げる。特性などでランクが下がらない場合は、回復の効果のみ発動する。すでにランクが最低の場合は失敗する。'),
(1994, 'しびれごな', 'くさ', 'status', '変化', NULL, 75, 20, 0, 0, 'single', 0, '相手を『まひ』状態にする。『でんき』タイプや『くさ』タイプ、特性『ぼうじん』、『ぼうじんゴーグル』を持っているのポケモンには無効。'),
(2005, 'クリアスモッグ', 'どく', 'special', '特殊', 50, NULL, 16, 0, 0, 'single', 0, '相手の能力ランクの変化を元に戻す。自分の命中率、相手の回避率に関係なく必ず命中する。'),
(2102, 'なまける', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが最大HPの半分回復する。'),
(2120, 'シェルブレード', 'みず', 'physical', '物理', 75, 95, 12, 0, 1, 'single', 0, '50%の確率で相手の『ぼうぎょ』ランクを1段階下げる。'),
(2236, 'シェルアームズ', 'どく', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, 'この技の分類は、物理・特殊それぞれの場合のダメージを比較して、大きい方の分類で攻撃する(物理の場合は自分の『こうげき』と相手の『ぼうぎょ』でダメージ計算)。20%の確率で相手を『どく』状態にする。'),
(2386, 'じばく', 'ノーマル', 'physical', '物理', 200, 100, 8, 0, 0, 'all_except_self', 1, '自分以外全員が対象。攻撃後、自分が『ひんし』状態になる。'),
(2393, 'ミラータイプ', 'ノーマル', 'status', '変化', NULL, NULL, 16, 0, 0, 'self', 0, '自分の『タイプ』を相手と同じ『タイプ』にする。相手がテラスタルしている時はテラスタイプをコピーするが、相手が『ステラ』タイプにテラスタルしている場合は元のタイプをコピーする。'),
(2397, 'くろいまなざし', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '『ゴースト』タイプではない相手は逃げたり、交代できなくなる。自分が場を離れると効果は消える。'),
(2399, 'ほろびのうた', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '3ターン終了後に、この技を使った時に出ていた自分を含むすべてのポケモンは『ひんし』状態になる。それまでに交代したポケモンは効果が消える。音系の技。相手の『みがわり』状態を貫通する。'),
(2422, 'ふしょくガス', 'どく', 'status', '変化', NULL, 100, 20, 0, 0, 'all_except_self', 1, '自分以外全員が対象。道具を持っているポケモンは、道具を持っていない状態になる。'),
(2441, 'ポルターガイスト', 'ゴースト', 'physical', '物理', 110, 90, 8, 0, 0, 'single', 0, '相手が道具を持っていない時は失敗する。なお、相手の道具を無効にする効果はない。'),
(2442, 'ゴーストダイブ', 'ゴースト', 'physical', '物理', 90, 100, 12, 0, 1, 'single', 0, '1ターン目に消えて、2ターン目に攻撃する。消えている間はほとんどの技を受けない。相手の『まもる』『みきり』『たたみがえし』『トーチカ』『キングシールド』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』の効果を受けない(『ダイウォール』を除く)。(なお、第7世代以降は相手が『ちいさくなる』を使っている時の必中2倍効果はない)'),
(2444, 'シャドーパンチ', 'ゴースト', 'physical', '物理', 60, NULL, 20, 0, 1, 'single', 0, '自分の命中率、相手の回避率に関係なく必ず命中する。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(2448, 'みちづれ', 'ゴースト', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, '自分は『みちづれ』状態となり、次の自分のターンまでに相手の攻撃で『ひんし』状態になると、相手も『ひんし』状態になる。ダイマックスしている相手には効果がない。第7世代以降は、連続で使うと必ず失敗する。'),
(2462, 'かげうち', 'ゴースト', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。'),
(2464, 'だいばくはつ', 'ノーマル', 'physical', '物理', 250, 100, 8, 0, 0, 'all_except_self', 1, '自分以外全員が対象。攻撃後、自分が『ひんし』状態になる。'),
(2618, 'アームハンマー', 'かくとう', 'physical', '物理', 100, 90, 12, 0, 1, 'single', 0, '攻撃後、自分の『すばやさ』ランクが1段階下がる。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(2622, 'ともえなげ', 'かくとう', 'physical', '物理', 60, 90, 12, 0, 1, 'single', 0, '必ず後攻になる(優先度:-6)。攻撃後、相手のポケモンを強制的に交代させる。野生のポケモンの場合は戦闘を終了する。ダイマックスしている相手には追加効果は無効。'),
(2652, 'ブレイククロー', 'ノーマル', 'physical', '物理', 75, 95, 12, 0, 1, 'single', 0, '50%の確率で相手の『ぼうぎょ』ランクを1段階下げる。'),
(2897, 'ハサミギロチン', 'ノーマル', 'physical', '物理', NULL, 30, 8, 0, 1, 'single', 0, '相手を『ひんし』状態にする。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。ダイマックスしている相手には無効。'),
(2939, 'ハードプレス', 'はがね', 'physical', '物理', NULL, 100, 12, 0, 1, 'single', 0, '相手の残りHPが多いほど威力が高くなる。(100×相手の残りHP÷相手の最大HP)が威力になる。'),
(3021, 'レイジングブル', 'ノーマル', 'physical', '物理', 90, 100, 12, 0, 1, 'single', 0, '『ケンタロス(パルデア)』が使う場合、自分のフォルムに合わせて『かくとう』『ほのお』『みず』タイプのいずれかに変化する。相手の技『リフレクター』『ひかりのかべ』『オーロラベール』を解除して攻撃する。'),
(3047, 'メガホーン', 'むし', 'physical', '物理', 120, 85, 12, 0, 1, 'single', 0, '通常攻撃。'),
(3076, 'つのドリル', 'ノーマル', 'physical', '物理', NULL, 30, 8, 0, 1, 'single', 0, '相手を『ひんし』状態にする。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。ダイマックスしている相手には無効。'),
(3390, 'へんしん', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '一時的に、相手と同じナンバー・グラフィックス・能力値・個体値・ランク・特性・技になる。ただしHP・持ち物・状態異常などはコピーされずそのままとなり、技のPPはすべて5になる。交代すると元に戻る。ダイマックスしている相手をコピーすると、元のポケモンの姿になる。'),
(3431, 'とける', 'どく', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『ぼうぎょ』ランクを2段階上げる。'),
(3513, 'きんぞくおん', 'はがね', 'status', '変化', NULL, 85, 20, 0, 0, 'single', 0, '音系の技。相手の『とくぼう』ランクを2段階下げる。'),
(3562, 'ふんえん', 'ほのお', 'special', '特殊', 80, 100, 16, 0, 0, 'all_except_self', 1, '自分以外全員が対象。30%の確率で相手を『やけど』状態にする。'),
(3658, 'ロックカット', 'いわ', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『すばやさ』ランクが2段階上がる。'),
(3772, 'サンダーダイブ', 'でんき', 'physical', '物理', 100, 95, 16, 0, 1, 'single', 0, '攻撃が外れたり、相手の技『まもる』などで失敗すると、自分の最大HPの半分のダメージを自分が受ける。相手が技『ちいさくなる』を使用していると必ず命中し、威力が2倍になる。'),
(3830, 'アイアンローラー', 'はがね', 'physical', '物理', 130, 100, 8, 0, 1, 'single', 0, '場の状態『グラスフィールド』『ミストフィールド』『エレキフィールド』『サイコフィールド』を解除し、元に戻す。いずれの状態でもない時は技が失敗する。'),
(3905, 'りゅうせいぐん', 'ドラゴン', 'special', '特殊', 130, 90, 8, 0, 0, 'single', 0, '攻撃後、100%の確率で自分の『とくこう』ランクが2段階下がる。'),
(4054, 'ソーラーブレード', 'くさ', 'physical', '物理', 125, 100, 12, 0, 1, 'single', 0, '1ターン目は攻撃せずに、2ターン目で攻撃する。天気が『にほんばれ』の時は1ターンためずに攻撃でき、『あめ』『ゆき』『すなあらし』の時は威力が半分になる。'),
(4194, 'ふんか', 'ほのお', 'special', '特殊', 150, 100, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。自分のHPが少ないほど技の威力が下がる。(150×自分の残りHP÷自分の最大HP)が威力。'),
(4301, 'ひゃっきやこう', 'ゴースト', 'special', '特殊', 65, 100, 16, 0, 0, 'single', 0, '30%の確率で相手を『やけど』状態にする。相手が状態異常の時、威力が2倍になる。'),
(4400, 'おだてる', 'あく', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手を1～4ターンの間『こんらん』状態にするが、相手の『とくこう』ランクを1段階上げてしまう。'),
(4524, 'であいがしら', 'むし', 'physical', '物理', 100, 100, 12, 0, 1, 'single', 0, '必ず先制できる(優先度:+2)。ただし、出た最初のターンしか成功しない。'),
(4536, 'ねばねばネット', 'むし', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '使用後、相手はポケモンを交代する度に、出てきたポケモンの『すばやさ』ランクが1段階下がる。『ひこう』タイプや特性『ふゆう』のポケモンは影響を受けない。'),
(4537, 'いかりのこな', 'むし', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+2)。そのターンの相手の技をすべて自分が受ける。ただし、全体技には効果がない。『くさ』タイプや特性『ぼうじん』、道具『ぼうじんゴーグル』を持っているポケモンには無効。ダブルバトル用。'),
(4546, 'どくのいと', 'どく', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手を『どく』状態にし、さらに『すばやさ』ランクを2段階下げる。(ポケモンSVまでは1段階だった)'),
(4560, 'つじぎり', 'あく', 'physical', '物理', 70, 100, 20, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(4590, 'コットンガード', 'くさ', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の『ぼうぎょ』ランクが3段階上がる。'),
(4591, 'わたほうし', 'くさ', 'status', '変化', NULL, 100, 20, 0, 0, 'all_opponents', 1, '相手全体が対象。相手の『すばやさ』ランクを2段階下げる。『くさ』タイプや特性『ぼうじん』、道具『ぼうじんゴーグル』を持っているポケモンには無効。'),
(4604, 'パラボラチャージ', 'でんき', 'special', '特殊', 65, 100, 20, 0, 0, 'all_except_self', 1, '自分以外全員が対象。相手に与えたダメージの半分だけ自分のHPが回復する。'),
(4609, 'じばそうさ', 'でんき', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '自分と味方全体の特性が『プラス』『マイナス』のポケモンの『ぼうぎょ』『とくぼう』ランクが1段階ずつ上がる。なお、『ダイウォール』は貫通しない。'),
(4760, 'みずびたし', 'みず', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手を『みず』タイプにする。'),
(5076, 'さむいギャグ', 'こおり', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '手持ちのポケモンと入れ替わる。また、5ターンの間、天気を『ゆき』にする(『こおり』タイプのポケモンは、『ぼうぎょ』が1.5倍になる)。'),
(5118, 'さきおくり', 'あく', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手は『すばやさ』に関係なく、行動が最後になる。ダブルバトル用。'),
(5194, 'ぶきみなじゅもん', 'エスパー', 'special', '特殊', 80, 100, 8, 0, 0, 'single', 0, '相手の最後に使った技のPPを3減らす。音系の技。相手の『みがわり』状態を貫通する。'),
(5269, 'すなじごく', 'じめん', 'physical', '物理', 35, 85, 16, 0, 0, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(5271, 'まきびし', 'じめん', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '使用後、相手はポケモンを交代する度にダメージを受ける。3回まで使うことができ、1回の時は相手の最大HPの1/8、2回の時は相手の最大HPの1/6、3回の時は相手の最大HPの1/4のダメージを与える。『ひこう』タイプ、特性『ふゆう』のポケモンはダメージを受けない。');
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(5289, 'てっていこうせん', 'はがね', 'special', '特殊', 140, 95, 8, 0, 0, 'single', 0, '自分のHPを最大HPの半分だけ減らす。『まもる』などで技が防がれた場合も、自分のHPは減る。'),
(5766, 'ドリルくちばし', 'ひこう', 'physical', '物理', 80, 100, 20, 0, 1, 'single', 0, '通常攻撃。'),
(5882, 'いかりのまえば', 'ノーマル', 'physical', '物理', NULL, 90, 12, 0, 1, 'single', 0, '相手のHPを残りHPの半分にする。残りHPが1の場合は1ダメージ。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(5935, 'ほうふく', 'あく', 'physical', '物理', NULL, 100, 12, 0, 1, 'single', 0, 'そのターンに最後に受けた技のダメージの1.5倍をその相手に与える。ダメージを受けていない時は失敗する。タイプ相性の影響を受けない。'),
(6569, 'メタルバースト', 'はがね', 'physical', '物理', NULL, 100, 12, 0, 0, 'single', 0, 'そのターンに最後に受けた技のダメージの1.5倍をその相手に与える。ダメージを受けていない時は失敗する。タイプ相性の影響を受けない。'),
(6572, 'すてゼリフ', 'あく', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『こうげき』『とくこう』ランクを1段階下げたあと、手持ちのポケモンと入れ替わる。音系の技。相手の『みがわり』状態を貫通する。'),
(6893, 'つぼをつく', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, 'ランダムで『こうげき』『ぼうぎょ』『とくこう』『とくぼう』『すばやさ』『回避率』『命中率』ランクのどれか1つが2段階上がる。この技は『ダイウォール』の効果も受けない。'),
(6917, 'とびひざげり', 'かくとう', 'physical', '物理', 130, 90, 12, 0, 1, 'single', 0, '攻撃が外れたり、相手の技『まもる』などで失敗すると、自分の最大HPの半分のダメージを自分が受ける。'),
(6918, 'かかとおとし', 'かくとう', 'physical', '物理', 120, 90, 12, 0, 1, 'single', 0, '30%の確率で相手を1～4ターンの間『こんらん』状態にする。攻撃が外れたり、相手の技『まもる』などで失敗すると、自分の最大HPの半分のダメージを自分が受ける。'),
(7937, 'ばくおんぱ', 'ノーマル', 'special', '特殊', 140, 100, 12, 0, 0, 'all_except_self', 1, '自分以外全員が対象。音系の技。相手の『みがわり』状態を貫通する。'),
(8000, 'なかまづくり', 'ノーマル', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手の特性を自分と同じ特性にする。ダイマックスしている相手には無効。'),
(8276, 'つららおとし', 'こおり', 'physical', '物理', 85, 90, 12, 0, 0, 'single', 0, '30%の確率で相手をひるませる。'),
(8397, 'ウッドハンマー', 'くさ', 'physical', '物理', 120, 100, 16, 0, 1, 'single', 0, '相手に与えたダメージの33%を自分も受ける。'),
(8422, 'ぶちかまし', 'じめん', 'physical', '物理', 120, 100, 8, 0, 1, 'single', 0, '攻撃後、自分の『ぼうぎょ』『とくぼう』ランクが1段階ずつ下がる。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(8616, 'つけあがる', 'あく', 'physical', '物理', 20, 100, 12, 0, 1, 'single', 0, '自分のいずれかの能力ランクが1つ上がる度に威力が20上がる。'),
(8745, 'キラースピン', 'どく', 'physical', '物理', 30, 100, 16, 0, 1, 'all_opponents', 1, '相手全体が対象。自分が受けている技『うずしお』『からではさむ』『サンダープリズン』『しめつける』『すなじごく』『トラバサミ』『ほのおのうず』『マグマストーム』『まきつく』『やどりぎのタネ』および自分の場の『ステルスロック』『どくびし』『まきびし』『ねばねばネット』の効果を解除する。また、100%の確率で相手を『どく』状態にする。'),
(8924, 'フラフラダンス', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'all_except_self', 1, '自分以外全員が対象。相手を1～4ターンの間『こんらん』状態にする。'),
(9323, 'ボーンラッシュ', 'じめん', 'physical', '物理', 30, 90, 12, 0, 0, 'single', 0, '1ターンに2～5回連続で攻撃する。'),
(9340, 'いのちがけ', 'かくとう', 'special', '特殊', NULL, 100, 8, 0, 0, 'single', 0, '自分のHPを0にし、その分のダメージを相手に与える。『ゴースト』タイプには無効だが、それ以外のタイプ相性の影響を受けない。'),
(9653, 'アイスハンマー', 'こおり', 'physical', '物理', 100, 90, 12, 0, 1, 'single', 0, '攻撃後、自分の『すばやさ』ランクが1段階下がる。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(9884, 'がんせきほう', 'いわ', 'physical', '物理', 150, 90, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(10112, 'クラブハンマー', 'みず', 'physical', '物理', 100, 95, 12, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(10280, 'アクアカッター', 'みず', 'physical', '物理', 70, 100, 20, 0, 0, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(10302, 'せいなるつるぎ', 'かくとう', 'physical', '物理', 90, 100, 16, 0, 1, 'single', 0, '相手の能力ランクの変化に関係なく、ダメージを与える。'),
(11337, 'ひけん・ちえなみ', 'あく', 'physical', '物理', 65, 90, 16, 0, 1, 'single', 0, '攻撃後、相手の場を『まきびし』状態にする。'),
(11411, 'なみだめ', 'ノーマル', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '相手の『こうげき』『とくこう』ランクを1段階ずつ下げる。自分の命中率、相手の回避率に関係なく必ず命中する。相手の『まもる』『みきり』『トーチカ』『ニードルガード』『ブロッキング』『スレッドトラップ』『かえんのまもり』の効果を受けない(『ダイウォール』を除く)。'),
(11496, 'ほおばる', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分が持っている『きのみ』を即座に使って効果を発動させ、さらに自分の『ぼうぎょ』ランクを2段階上げる。'),
(11547, 'ニードルガード', 'くさ', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '必ず先制でき(優先度:+4)、そのターンの間、相手の攻撃を防ぐと同時に、接触技(直接攻撃)で攻撃した相手に相手の最大HPの1/8のダメージを与える。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。ダイマックス技や第7世代のZワザの攻撃技は貫通し、1/4のダメージを受ける。'),
(11818, 'シンプルビーム', 'ノーマル', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '相手の特性が『たんじゅん』になる。(ダブルバトルで味方に使うと良い)'),
(12209, 'パワーシェア', 'エスパー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '自分と相手の『こうげき』と『とくこう』の数値をそれぞれ足して、互いに半分ずつに分ける。'),
(12377, 'ナイトバースト', 'あく', 'special', '特殊', 90, 95, 12, 0, 0, 'single', 0, '40%の確率で相手の命中率を1段階下げる。'),
(13024, 'うらみつらみ', 'ゴースト', 'special', '特殊', 75, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『こうげき』ランクを1段階下げる。'),
(13517, 'トラバサミ', 'はがね', 'physical', '物理', 35, 100, 16, 0, 1, 'single', 0, '相手を『バインド』状態にして、4～5ターンの間、毎ターン終了後最大HPの1/8のダメージを与え、その間『ゴースト』タイプではない相手は逃げたり交代できない。'),
(13813, 'ほのおのまい', 'ほのお', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '50%の確率で自分の『とくこう』ランクが1段階上がる。'),
(13828, 'ちょうのまい', 'むし', 'status', '変化', NULL, NULL, 20, 0, 0, 'self', 0, '自分の『とくこう』『とくぼう』『すばやさ』ランクが1段階ずつ上がる。'),
(14224, 'みずしゅりけん', 'みず', 'special', '特殊', 15, 100, 20, 0, 0, 'single', 0, '必ず先制できる(優先度:+1)。1ターンに2～5回連続で攻撃する。'),
(14561, 'はめつのひかり', 'フェアリー', 'special', '特殊', 140, 90, 8, 0, 0, 'single', 0, '相手に与えたダメージの1/2を自分も受ける。'),
(15134, 'キングシールド', 'はがね', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '必ず先制でき(優先度:+4)、そのターンの間、相手の攻撃技を受けない。また、接触技(直接攻撃)で攻撃してきた相手の『こうげき』ランクを1段階下げる(第7世代までは2段階)。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。ダイマックス技や第7世代のZワザの攻撃技は貫通し、1/4のダメージを受ける。'),
(15238, 'アロマミスト', 'フェアリー', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '味方1体の『とくぼう』を1段階上げる(ダブルバトル用)。この技は『ダイウォール』の効果も受けない。'),
(15370, 'しっぽきり', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分のHPを最大HPの半分だけ減らして『みがわり』状態となり、『みがわり』状態のまま手持ちのポケモンに入れ替わる。『みがわり』のHPは最大HPの1/4になる。'),
(15398, 'そうでん', 'でんき', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '相手が技を出す前に使用すると、そのターン相手の攻撃は『でんき』タイプになる。'),
(15681, 'フライングプレス', 'かくとう', 'physical', '物理', 100, 95, 12, 0, 1, 'single', 0, 'この技は『かくとう』タイプであると同時に『ひこう』タイプでもある。相手が技『ちいさくなる』を使用していると必ず命中し、威力が2倍になる。'),
(15920, 'たてこもる', 'はがね', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の『ぼうぎょ』ランクを2段階上げる。'),
(16039, 'フェアリーロック', 'フェアリー', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '次のターン終了まで、すべての『ゴースト』タイプではないポケモンは逃げたり交代できなくなる。'),
(16045, 'ロックオン', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '次のターン、使った相手に自分の技が必ず命中する。'),
(16065, 'ウッドホーン', 'くさ', 'physical', '物理', 75, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの半分だけ自分のHPが回復する。'),
(16074, 'もりののろい', 'くさ', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『タイプ』に『くさ』タイプを追加する。'),
(16175, 'ハロウィン', 'ゴースト', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『タイプ』に『ゴースト』タイプを追加する。'),
(16495, 'ひょうざんおろし', 'こおり', 'physical', '物理', 120, 85, 12, 0, 0, 'single', 0, '30%の確率で相手をひるませる。'),
(16654, 'かげぬい', 'ゴースト', 'physical', '物理', 90, 100, 12, 0, 0, 'single', 0, '『ゴースト』タイプではない相手は逃げたり、交代できなくなる。自分が場を離れると効果は消える。'),
(16720, '3ぼんのや', 'かくとう', 'physical', '物理', 90, 100, 12, 0, 0, 'single', 0, '急所に当たりやすい(急所ランク:+1)。50%の確率で、相手の『ぼうぎょ』ランクを1段階下げる。30%の確率で相手をひるませる。'),
(16864, 'うたかたのアリア', 'みず', 'special', '特殊', 90, 100, 12, 0, 0, 'all_except_self', 1, '自分以外全員が対象。相手の『やけど』状態を治す。音系の技。相手の『みがわり』状態を貫通する。'),
(16937, 'くちばしキャノン', 'ひこう', 'physical', '物理', 120, 100, 8, 0, 0, 'single', 0, '必ず後攻になる(優先度:-3)。技が発動する前に接触技(直接攻撃)を受けると、そのポケモンを『やけど』状態にする。技はそのまま受ける。'),
(17142, 'アクセルロック', 'いわ', 'physical', '物理', 40, 100, 20, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。'),
(17353, 'トーチカ', 'どく', 'status', '変化', NULL, NULL, 8, 0, 0, 'single', 0, '必ず先制でき(優先度:+4)、そのターンの間、相手の攻撃を防ぐと同時に、接触技(直接攻撃)で攻撃した相手を『どく』状態にする。連続で使うと失敗しやすくなる。具体的には、最初は成功するが、使う度に成功率が1/3になっていく(失敗するとリセットされる)。ダイマックス技や第7世代のZワザの攻撃技は貫通し、1/4のダメージを受ける。'),
(17507, 'ほのおのムチ', 'ほのお', 'physical', '物理', 90, 100, 16, 0, 1, 'single', 0, '100%の確率で相手の『ぼうぎょ』ランクを1段階下げる。'),
(17581, 'トロピカルキック', 'くさ', 'physical', '物理', 85, 100, 16, 0, 1, 'single', 0, '100%の確率で相手の『こうげき』ランクを1段階下げる。'),
(17664, 'さいはい', 'エスパー', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '相手が最後に使用した技をその場でもう一度使わせる。『はかいこうせん』など反動のある技や、ターン技、ダイマックス技、『ダイマックスほう』など一部の技は失敗する。'),
(18001, 'おたけび', 'ノーマル', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手の『こうげき』『とくこう』ランクを1段階ずつ下げる。音系の技。相手の『みがわり』状態を貫通する。'),
(18052, 'スケイルノイズ', 'ドラゴン', 'special', '特殊', 110, 100, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。攻撃後、自分の『ぼうぎょ』ランクが1段階下がる。音系の技。相手の『みがわり』状態を貫通する。'),
(18055, 'ソウルビート', 'ドラゴン', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, '自分のHPを最大HPの1/3だけ減らし、自分のすべての『のうりょく』ランクを1段階ずつ上げる。音系の技。'),
(18143, 'Gのちから', 'くさ', 'physical', '物理', 90, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『ぼうぎょ』ランクを1段階下げる。場が『じゅうりょく』状態の時、威力が1.5倍になる。'),
(18195, 'りんごさん', 'くさ', 'special', '特殊', 90, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『とくぼう』ランクを1段階下げる。'),
(18284, 'おちゃかい', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, '場にいるすべてのポケモンが、それぞれが持っている『きのみ』を即座に使って効果を発動させる。'),
(18353, 'まほうのこな', 'エスパー', 'status', '変化', NULL, 100, 20, 0, 0, 'single', 0, '相手を『エスパー』タイプにする。『くさ』タイプや特性『ぼうじん』、道具『ぼうじんゴーグル』を持っているポケモンには無効。'),
(18609, 'デコレーション', 'フェアリー', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '相手の『こうげき』『とくこう』ランクを2段階ずつ上げる(主にダブルバトルで味方に使うと良い)。この技は『ダイウォール』の効果も受けない。'),
(18637, 'オーラぐるま', 'でんき', 'physical', '物理', 110, 100, 12, 0, 0, 'single', 0, '100%の確率で自分の『すばやさ』ランクが1段階上がる。自分の『モルペコ』のフォルムが『まんぷくもよう』の時は『でんき』タイプ、『はらぺこもよう』の時は『あく』タイプの技になる。'),
(18733, 'ドラゴンアロー', 'ドラゴン', 'physical', '物理', 50, 100, 12, 0, 0, 'single', 0, '1ターンに2回連続で攻撃する。相手が2匹いる場合は、それぞれに1回ずつ攻撃する。ただし、技『まもる』やタイプ相性などでダメージを与えられない時は片方に2回攻撃する。'),
(18780, 'バリアーラッシュ', 'エスパー', 'physical', '物理', 90, 90, 12, 0, 1, 'single', 0, '攻撃後、100%の確率で自分の『ぼうぎょ』ランクが1段階上がる。'),
(18859, 'がんせきアックス', 'いわ', 'physical', '物理', 65, 90, 16, 0, 1, 'single', 0, '攻撃後、相手の場を『ステルスロック』状態にする。'),
(18933, 'おはかまいり', 'ゴースト', 'physical', '物理', 50, 100, 12, 0, 0, 'single', 0, 'これまでに『ひんし』状態になった味方のポケモン1体につき、威力が50上がる。'),
(19023, 'フェイタルクロー', 'どく', 'physical', '物理', 80, 100, 16, 0, 1, 'single', 0, '30%の確率で、相手を『どく』『まひ』『ねむり』状態のいずれかにする。'),
(19077, 'トリックフラワー', 'くさ', 'physical', '物理', 70, NULL, 12, 0, 0, 'single', 0, '必ず急所に当たる。自分の命中率、相手の回避率に関係なく必ず命中する。'),
(19158, 'フレアソング', 'ほのお', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '100%の確率で自分の『とくこう』ランクを1段階上げる。音系の技。相手の『みがわり』状態を貫通する。'),
(19204, 'アクアステップ', 'みず', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '100%の確率で自分の『すばやさ』ランクが1段階上がる。'),
(19277, 'ルミナコリジョン', 'エスパー', 'special', '特殊', 80, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『とくぼう』ランクを2段階下げる。'),
(19341, 'ツインビーム', 'エスパー', 'special', '特殊', 40, 100, 12, 0, 0, 'single', 0, '1ターンに2回連続で攻撃する。'),
(19405, 'ジェットパンチ', 'みず', 'physical', '物理', 60, 100, 16, 0, 1, 'single', 0, '必ず先制できる(優先度:+1)。特性『てつのこぶし』の時、威力が1.2倍になる。'),
(19520, 'ハバネロエキス', 'くさ', 'status', '変化', NULL, NULL, 16, 0, 0, 'single', 0, '相手の『こうげき』ランクを2段階上げ、『ぼうぎょ』ランクを2段階下げる。'),
(19682, 'ネズミざん', 'ノーマル', 'physical', '物理', 20, 90, 12, 0, 1, 'single', 0, '1ターンに外れるまで最大10回連続で攻撃する。'),
(19686, 'おかたづけ', 'ノーマル', 'status', '変化', NULL, NULL, 12, 0, 0, 'single', 0, 'お互いの『みがわり』状態、両方の場の『まきびし』『ステルスロック』『ねばねばネット』『どくびし』の効果を解除する。また、自分の『こうげき』と『すばやさ』ランクが1段階ずつ上がる。'),
(19749, 'しおづけ', 'いわ', 'physical', '物理', 40, 100, 16, 0, 0, 'single', 0, '追加効果として相手を『しおづけ』状態にして、毎ターン終了後、相手の最大HPの1/16のダメージを与える。相手が『はがね』や『みず』タイプの場合は、毎ターン最大HPの1/8のダメージになる。(ポケモンSVでは通常1/8、はがね・みずタイプは1/4のダメージだった)'),
(19911, 'デカハンマー', 'はがね', 'physical', '物理', 160, 100, 8, 0, 0, 'single', 0, 'この技は2回連続で出すことができない。'),
(19939, 'アーマーキャノン', 'ほのお', 'special', '特殊', 120, 100, 8, 0, 0, 'single', 0, '攻撃後、自分の『ぼうぎょ』『とくぼう』ランクが1段階ずつ下がる。'),
(19991, 'むねんのつるぎ', 'ほのお', 'physical', '物理', 90, 100, 12, 0, 1, 'single', 0, '相手に与えたダメージの半分だけ自分のHPが回復する。'),
(20069, 'ドゲザン', 'あく', 'physical', '物理', 85, NULL, 12, 0, 1, 'single', 0, '自分の命中率、相手の回避率に関係なく必ず命中する。'),
(20124, 'みずあめボム', 'くさ', 'special', '特殊', 60, 90, 12, 0, 0, 'single', 0, '100%の確率で、相手を『あめまみれ』状態にする。3ターンの間、毎ターン終了時に相手の『すばやさ』ランクが1段階下がる。'),
(20146, 'きまぐレーザー', 'ドラゴン', 'special', '特殊', 80, 100, 8, 0, 0, 'single', 0, '30%程度の確率で、威力が2倍になる。'),
(20167, 'エレクトロビーム', 'でんき', 'special', '特殊', 130, 100, 12, 0, 0, 'single', 0, '1ターン目に100%の確率で自分の『とくこう』ランクを1段階上げ、2ターン目で攻撃する。天気が『あめ』の時は1ターンためずに攻撃できる。'),
(20222, 'シャカシャカほう', 'くさ', 'special', '特殊', 80, 90, 16, 0, 0, 'all_opponents', 1, '相手全体が対象。相手に与えたダメージの半分だけ自分のHPが回復する。また、20%の確率で相手を『やけど』状態にする。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。また、相手の『こおり』状態を治す。'),
(20246, 'ゴールドラッシュ', 'はがね', 'special', '特殊', 120, 95, 8, 0, 0, 'all_opponents', 1, '相手全体が対象。攻撃後、自分の「とくこう」ランクが2段階下がる。'),
(20247, 'ソウルクラッシュ', 'フェアリー', 'physical', '物理', 75, 100, 16, 0, 1, 'single', 0, '100%の確率で相手の「とくこう」ランクを1段階下げる。'),
(20248, 'どくばりセンボン', 'どく', 'physical', '物理', 60, 100, 12, 0, 0, 'single', 0, '50%の確率で相手を「どく」状態にする。相手が「どく」「もうどく」状態の時、威力が2倍になる。'),
(20249, 'はいすいのじん', 'かくとう', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, '自分のすべての能力ランクが1段階ずつ上がるが、逃げたり交代できなくなる。2回目からは失敗する。'),
(20250, 'ひっくりかえす', 'あく', 'status', '変化', NULL, NULL, 20, 0, 0, 'single', 0, '相手のすべての能力ランクのプラスとマイナスを逆にする。'),
(20251, 'ふんどのこぶし', 'ゴースト', 'physical', '物理', 50, 100, 12, 0, 1, 'single', 0, 'これまでに受けた攻撃1回につき威力が50上がる。最大威力は350。手持ちに戻るとリセットされる。'),
(20252, 'きりさく', 'ノーマル', 'physical', '物理', 80, 100, 20, 0, 1, 'single', 0, '急所に当たりやすい(急所ランク:+1)。'),
(20253, 'ミルクのみ', 'ノーマル', 'status', '変化', NULL, NULL, 8, 0, 0, 'self', 0, 'HPが最大HPの半分回復する。'),
(20254, 'ドラムアタック', 'くさ', 'physical', '物理', 80, 100, 12, 0, 0, 'single', 0, '100%の確率で相手の『すばやさ』ランクを1段階下げる。'),
(20255, 'コートチェンジ', 'ノーマル', 'status', '変化', NULL, 100, 12, 0, 0, 'single', 0, 'お互いの場の状態『オーロラベール』『おいかぜ』『しろいきり』『しんぴのまもり』『ステルスロック』『どくびし』『ねばねばネット』『ひかりのかべ』『まきびし』『リフレクター』『キョダイベンタツ』『キョダイゴクエン』『キョダイホウゲキ』『キョダイフンセキ』『キョダイコウジン』を入れ替える。経過ターン数は引き継がれる。');
INSERT INTO moves (id, name_ja, type_name, damage_class, damage_class_ja, power, accuracy, pp, priority, contact, target, is_spread, effect_text) VALUES
(20256, 'かえんボール', 'ほのお', 'physical', '物理', 120, 90, 8, 0, 0, 'single', 0, '10%の確率で相手を『やけど』状態にする。自分が『こおり』状態の時でも使う事ができ、使うと『こおり』状態が治る。'),
(20257, 'ねらいうち', 'みず', 'special', '特殊', 85, 100, 16, 0, 0, 'single', 0, '急所に当たりやすい(急所ランク:+1)。特性『ひらいしん』『よびみず』や技『いかりのこな』『このゆびとまれ』『サイドチェンジ』『スポットライト』の攻撃対象を変更する効果の影響を受けずに攻撃できる。'),
(20258, 'オーバードライブ', 'でんき', 'special', '特殊', 80, 100, 12, 0, 0, 'all_opponents', 1, '相手全体が対象。音系の技。相手の『みがわり』状態を貫通する。'),
(20259, 'ギアチェンジ', 'はがね', 'status', '変化', NULL, NULL, 12, 0, 0, 'self', 0, '自分の『すばやさ』ランクが2段階、『こうげき』ランクが1段階上がる。'),
(20260, 'たこがため', 'かくとう', 'status', '変化', NULL, 100, 16, 0, 0, 'single', 0, '『ゴースト』タイプではない相手は逃げたり、交代できなくなる。相手はその間、毎ターン『ぼうぎょ』『とくぼう』ランクが1段階ずつ下がる。ターン上限はない。'),
(20261, 'スターアサルト', 'かくとう', 'physical', '物理', 170, 100, 8, 0, 0, 'single', 0, '使用した次のターンは行動できない。'),
(20262, 'びりびりちくちく', 'でんき', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '30%の確率で相手をひるませる。'),
(20263, 'さいきのいのり', 'ノーマル', 'status', '変化', NULL, NULL, 1, 0, 0, 'self', 0, '手持ちの『ひんし』状態のポケモンを、最大HPの半分だけ回復させる。'),
(20264, 'でんこうそうげき', 'でんき', 'physical', '物理', 120, 100, 8, 0, 1, 'single', 0, '攻撃後、自分は『でんき』タイプではなくなる。自分が『でんき』タイプではない時は失敗する。'),
(20265, 'くらいつく', 'あく', 'physical', '物理', 80, 100, 12, 0, 1, 'single', 0, '自分と相手のどちらかが『ひんし』になるまで、どちらも逃げたり交代できなくなる。自分か相手が『ゴースト』タイプの場合は追加効果はない。'),
(20266, 'きょけんとつげき', 'ドラゴン', 'physical', '物理', 120, 100, 8, 0, 1, 'single', 0, '次の自分のターンまで、相手から自分への攻撃が必ず命中し、受けるダメージが2倍になる。');

